// SVG 1 — FLAG STATE TYPES
// ══════════════════════════════════════
function FlagStatesSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const flags = [
    { id:"open", icon:"🏴", color:C.orange,
      label:{fr:"Pavillons de complaisance\n(Open Registries)",en:"Flags of Convenience\n(Open Registries)",es:"Pabellones de conveniencia\n(Registros abiertos)",pt:"Bandeiras de conveniência\n(Registos abertos)"},
      examples:{fr:"Panama 🇵🇦 · Liberia 🇱🇷 · Marshall Islands 🇲🇭\nBahamas 🇧🇸 · Vanuatu 🇻🇺 · Cambodge 🇰🇭",en:"Panama 🇵🇦 · Liberia 🇱🇷 · Marshall Islands 🇲🇭\nBahamas 🇧🇸 · Vanuatu 🇻🇺 · Cambodia 🇰🇭",es:"Panamá 🇵🇦 · Liberia 🇱🇷 · Islas Marshall 🇲🇭\nBahamas 🇧🇸 · Vanuatu 🇻🇺 · Camboya 🇰🇭",pt:"Panamá 🇵🇦 · Libéria 🇱🇷 · Ilhas Marshall 🇲🇭\nBahamas 🇧🇸 · Vanuatu 🇻🇺 · Camboja 🇰🇭"},
      desc:{fr:"AVANTAGES POUR L'ARMATEUR :\n→ Taxes très basses (voire nulles)\n→ Équipage de toute nationalité (salaires bas)\n→ Réglementation moins stricte\n→ Immatriculation rapide et peu coûteuse\n→ Anonymat du propriétaire possible\n\nRISQUES :\n→ Contrôles moins stricts = navires sous-normes\n→ Paris MOU : souvent sur liste grise ou noire\n→ PSC : inspection systématique\n→ Abandon d'équipage plus fréquent\n\n⚠️ 73% de la flotte mondiale navigue sous pavillon de complaisance",en:"ADVANTAGES FOR SHIPOWNER:\n→ Very low (or zero) taxes\n→ Crew of any nationality (low wages)\n→ Less strict regulation\n→ Fast, cheap registration\n→ Owner anonymity possible\n\nRISKS:\n→ Less strict controls = substandard vessels\n→ Paris MOU: often on grey or black list\n→ PSC: systematic inspection\n→ Crew abandonment more frequent\n\n⚠️ 73% of world fleet sails under flag of convenience",es:"VENTAJAS PARA EL ARMADOR:\n→ Impuestos muy bajos (o nulos)\n→ Tripulación de cualquier nacionalidad (salarios bajos)\n→ Reglamentación menos estricta\n→ Matriculación rápida y barata\n→ Anonimato del propietario posible\n\nRIESGOS:\n→ Controles menos estrictos = buques subestándar\n→ Paris MOU: a menudo en lista gris o negra\n→ PSC: inspección sistemática\n\n⚠️ El 73% de la flota mundial navega bajo pabellón de conveniencia",pt:"VANTAGENS PARA O ARMADOR:\n→ Impostos muito baixos (ou nulos)\n→ Tripulação de qualquer nacionalidade (salários baixos)\n→ Regulamentação menos rigorosa\n→ Registo rápido e barato\n→ Anonimato do proprietário possível\n\nRISCOS:\n→ Controlos menos rigorosos = navios abaixo do padrão\n→ Paris MOU: frequentemente na lista cinzenta ou negra\n→ PSC: inspeção sistemática\n\n⚠️ 73% da frota mundial navega sob bandeira de conveniência"}},
    { id:"strict", icon:"🚩", color:C.blue2,
      label:{fr:"Pavillons stricts\n(Registres fermés)",en:"Strict Flags\n(Closed Registries)",es:"Pabellones estrictos\n(Registros cerrados)",pt:"Bandeiras rigorosas\n(Registos fechados)"},
      examples:{fr:"Royaume-Uni 🇬🇧 · Norvège 🇳🇴 · Pays-Bas 🇳🇱\nJapon 🇯🇵 · Allemagne 🇩🇪 · France 🇫🇷",en:"United Kingdom 🇬🇧 · Norway 🇳🇴 · Netherlands 🇳🇱\nJapan 🇯🇵 · Germany 🇩🇪 · France 🇫🇷",es:"Reino Unido 🇬🇧 · Noruega 🇳🇴 · Países Bajos 🇳🇱\nJapón 🇯🇵 · Alemania 🇩🇪 · Francia 🇫🇷",pt:"Reino Unido 🇬🇧 · Noruega 🇳🇴 · Países Baixos 🇳🇱\nJapão 🇯🇵 · Alemanha 🇩🇪 · França 🇫🇷"},
      desc:{fr:"CARACTÉRISTIQUES :\n→ Navires appartenant à des nationaux\n→ Contrôles rigoureux · inspections fréquentes\n→ Taxes normales\n→ Équipage généralement national\n→ Forte présence sur la whitelist OMI\n\nAVANTAGES :\n→ Meilleure réputation · accès facilité aux ports\n→ PSC : moins souvent ciblés\n→ Assurances moins chères\n→ Litiges réglés plus facilement\n\nINDICATEUR :\nTaux de détention PSC très faible",en:"CHARACTERISTICS:\n→ Vessels owned by nationals\n→ Rigorous controls · frequent inspections\n→ Normal taxes\n→ Generally national crew\n→ Strong presence on IMO whitelist\n\nADVANTAGES:\n→ Better reputation · easier port access\n→ PSC: less frequently targeted\n→ Cheaper insurance\n→ Disputes resolved more easily\n\nINDICATOR:\nVery low PSC detention rate",es:"CARACTERÍSTICAS:\n→ Buques pertenecientes a nacionales\n→ Controles rigurosos · inspecciones frecuentes\n→ Impuestos normales\n→ Tripulación generalmente nacional\n→ Fuerte presencia en la lista blanca OMI\n\nVENTAJAS:\n→ Mejor reputación · acceso más fácil a los puertos\n→ PSC: menos frecuentemente inspeccionados\n→ Seguros más baratos\n→ Litigios resueltos más fácilmente",pt:"CARACTERÍSTICAS:\n→ Navios pertencentes a nacionais\n→ Controlos rigorosos · inspeções frequentes\n→ Impostos normais\n→ Tripulação geralmente nacional\n→ Forte presença na lista branca IMO\n\nVANTAGENS:\n→ Melhor reputação · acesso facilitado aos portos\n→ PSC: menos frequentemente inspecionados\n→ Seguros mais baratos\n→ Litígios resolvidos mais facilmente"}},
    { id:"second", icon:"⚓", color:C.teal,
      label:{fr:"Seconds registres\n(Registres bis)",en:"Second Registries\n(Offshore Registries)",es:"Segundos registros\n(Registros bis)",pt:"Segundos registos\n(Registos secundários)"},
      examples:{fr:"NIS (Norvège) · DIS (Danemark)\nMADEIRA (Portugal) · KRS (Allemagne)",en:"NIS (Norway) · DIS (Denmark)\nMADEIRA (Portugal) · KRS (Germany)",es:"NIS (Noruega) · DIS (Dinamarca)\nMADEIRA (Portugal) · KRS (Alemania)",pt:"NIS (Noruega) · DIS (Dinamarca)\nMADEIRA (Portugal) · KRS (Alemanha)"},
      desc:{fr:"COMPROMIS ENTRE LES DEUX SYSTÈMES :\n→ Maintien sous pavillon national\n→ Mais avantages fiscaux réduits\n→ Équipage mixte (national + international)\n→ Contrôles rigoureux maintenus\n\nOBJECTIF :\nRetenir les armateurs nationaux qui seraient tentés par les pavillons de complaisance\n\nRÉSULTAT :\n→ Flotte maintenue sous pavillon national\n→ Emplois maritimes préservés\n→ Bonne performance PSC",en:"COMPROMISE BETWEEN BOTH SYSTEMS:\n→ Maintained under national flag\n→ But reduced tax advantages\n→ Mixed crew (national + international)\n→ Rigorous controls maintained\n\nOBJECTIVE:\nRetain national shipowners who might be tempted by flags of convenience\n\nRESULT:\n→ Fleet maintained under national flag\n→ Maritime jobs preserved\n→ Good PSC performance",es:"COMPROMISO ENTRE AMBOS SISTEMAS:\n→ Mantenimiento bajo pabellón nacional\n→ Pero ventajas fiscales reducidas\n→ Tripulación mixta (nacional + internacional)\n→ Controles rigurosos mantenidos\n\nOBJETIVO:\nRetener a los armadores nacionales tentados por los pabellones de conveniencia\n\nRESULTADO:\n→ Flota mantenida bajo pabellón nacional\n→ Empleo marítimo preservado\n→ Buena actuación PSC",pt:"COMPROMISSO ENTRE OS DOIS SISTEMAS:\n→ Mantido sob bandeira nacional\n→ Mas vantagens fiscais reduzidas\n→ Tripulação mista (nacional + internacional)\n→ Controlos rigorosos mantidos\n\nOBJETIVO:\nReter os armadores nacionais tentados pelas bandeiras de conveniência\n\nRESULTADO:\n→ Frota mantida sob bandeira nacional\n→ Emprego marítimo preservado\n→ Boa desempenho PSC"}},
    { id:"obligations", icon:"📋", color:C.green,
      label:{fr:"Obligations de l'État\ndu pavillon",en:"Flag State\nObligations",es:"Obligaciones del\nEstado de pabellón",pt:"Obrigações do\nEstado de bandeira"},
      examples:{fr:"SOLAS · MARPOL · STCW · MLC · COLREG",en:"SOLAS · MARPOL · STCW · MLC · COLREG",es:"SOLAS · MARPOL · STCW · MLC · COLREG",pt:"SOLAS · MARPOL · STCW · MLC · COLREG"},
      desc:{fr:"OBLIGATIONS LÉGALES (UNCLOS Art.94) :\n1. Exercer sa juridiction sur ses navires\n2. Maintenir un registre des navires\n3. Assurer la conformité SOLAS/MARPOL/STCW\n4. Vérifier les qualifications de l'équipage\n5. Délivrer les certificats requis\n6. Mener les enquêtes sur les accidents\n7. Être sur la whitelist OMI (STCW)\n\nSI L'ÉTAT DU PAVILLON DÉFAILLE :\n→ PSC peut inspecter plus fréquemment\n→ Navires sur liste noire Paris MOU\n→ Exclusion possible de la whitelist OMI\n→ Responsabilité internationale de l'État",en:"LEGAL OBLIGATIONS (UNCLOS Art.94):\n1. Exercise jurisdiction over its vessels\n2. Maintain a ship register\n3. Ensure SOLAS/MARPOL/STCW compliance\n4. Verify crew qualifications\n5. Issue required certificates\n6. Conduct accident investigations\n7. Be on IMO whitelist (STCW)\n\nIF FLAG STATE FAILS:\n→ PSC can inspect more frequently\n→ Vessels on Paris MOU black list\n→ Possible exclusion from IMO whitelist\n→ State's international responsibility",es:"OBLIGACIONES LEGALES (CONVEMAR Art.94):\n1. Ejercer jurisdicción sobre sus buques\n2. Mantener un registro de buques\n3. Asegurar el cumplimiento SOLAS/MARPOL/STCW\n4. Verificar las titulaciones de la tripulación\n5. Expedir los certificados requeridos\n6. Realizar investigaciones sobre accidentes\n7. Estar en la lista blanca OMI (STCW)\n\nSI EL ESTADO DE PABELLÓN FALLA:\n→ PSC puede inspeccionar con más frecuencia\n→ Buques en lista negra Paris MOU\n→ Posible exclusión de la lista blanca OMI",pt:"OBRIGAÇÕES LEGAIS (UNCLOS Art.94):\n1. Exercer jurisdição sobre os seus navios\n2. Manter um registo de navios\n3. Assegurar conformidade SOLAS/MARPOL/STCW\n4. Verificar as qualificações da tripulação\n5. Emitir os certificados requeridos\n6. Conduzir investigações de acidentes\n7. Estar na lista branca IMO (STCW)\n\nSE O ESTADO DE BANDEIRA FALHAR:\n→ PSC pode inspecionar mais frequentemente\n→ Navios na lista negra Paris MOU\n→ Possível exclusão da lista branca IMO"},},
  ];
  const sel_ = sel!==null ? flags[sel] : null;
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
        {flags.map((f,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)}
            style={{padding:"10px 6px",borderRadius:12,cursor:"pointer",textAlign:"center",
              background:sel===i?`${f.color}22`:"rgba(255,255,255,0.04)",
              border:`1.5px solid ${sel===i?f.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:22,marginBottom:3}}>{f.icon}</div>
            <div style={{fontSize:8,color:sel===i?f.color:C.muted,fontWeight:700,lineHeight:1.3,whiteSpace:"pre-line"}}>{f.label[lang]||f.label.fr}</div>
          </div>
        ))}
      </div>
      {sel_&&<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}12`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:sel_.color,marginBottom:4}}>{sel_.icon} {(sel_.label[lang]||sel_.label.fr).replace('\n',' ')}</div>
        <div style={{fontSize:10,color:sel_.color,fontWeight:700,marginBottom:6}}>
          {lang==="fr"?"Exemples:":lang==="en"?"Examples:":lang==="es"?"Ejemplos:":"Exemplos:"} {sel_.examples[lang]||sel_.examples.fr}
        </div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{sel_.desc[lang]||sel_.desc.fr}</div>
      </div>}
    </div>
  );
}

