// SVG 2 — MOU SYSTEMS
// ══════════════════════════════════════
function MOUSystemsSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const mous = [
    { id:"paris", icon:"🇪🇺", color:C.blue2,
      label:{fr:"Paris MOU",en:"Paris MOU",es:"Paris MOU",pt:"Paris MOU"},
      zone:{fr:"Europe + Atlantique Nord",en:"Europe + North Atlantic",es:"Europa + Atlántico Norte",pt:"Europa + Atlântico Norte"},
      members:{fr:"27 États membres",en:"27 member states",es:"27 Estados miembros",pt:"27 estados membros"},
      desc:{fr:"Fondé en 1982 · Siège : Paris\nLe plus ancien et le plus strict\n\nSPÉCIFICITÉS :\n→ Base de données commune THETIS\n→ Liste blanche · grise · noire des pavillons\n→ Ciblage des navires à risque\n→ Partage des informations d'inspection\n→ Objectif : 25% des navires inspectés/an\n→ Campagnes thématiques annuelles\n\nCRITÈRES CIBLAGE :\nÂge · pavillon · performances passées\nType de navire · historique déficiences",en:"Founded 1982 · Headquarters: Paris\nOldest and strictest\n\nSPECIFICS:\n→ Common database THETIS\n→ White · grey · black flag lists\n→ Risk vessel targeting\n→ Inspection information sharing\n→ Target: 25% vessels inspected/year\n→ Annual thematic campaigns\n\nTARGETING CRITERIA:\nAge · flag · past performance\nVessel type · deficiency history",es:"Fundado en 1982 · Sede: París\nEl más antiguo y estricto\n\nESPECIFICIDADES:\n→ Base de datos común THETIS\n→ Lista blanca · gris · negra de pabellones\n→ Selección de buques de riesgo\n→ Intercambio de información de inspección\n→ Objetivo: 25% de los buques inspeccionados/año\n→ Campañas temáticas anuales",pt:"Fundado em 1982 · Sede: Paris\nO mais antigo e mais rigoroso\n\nESPECIFICIDADES:\n→ Base de dados comum THETIS\n→ Lista branca · cinzenta · negra de bandeiras\n→ Seleção de navios de risco\n→ Partilha de informações de inspeção\n→ Objetivo: 25% navios inspecionados/ano\n→ Campanhas temáticas anuais"}},
    { id:"tokyo", icon:"🌏", color:C.red,
      label:{fr:"Tokyo MOU",en:"Tokyo MOU",es:"Tokyo MOU",pt:"Tokyo MOU"},
      zone:{fr:"Asie-Pacifique",en:"Asia-Pacific",es:"Asia-Pacífico",pt:"Ásia-Pacífico"},
      members:{fr:"21 États membres",en:"21 member states",es:"21 Estados miembros",pt:"21 estados membros"},
      desc:{fr:"Fondé en 1993 · Siège : Tokyo\nDeuxième MOU en importance mondiale\n\nSPÉCIFICITÉS :\n→ Base de données APCIS\n→ Couvre le plus grand trafic maritime mondial\n→ Détroits de Malacca · Mer de Chine\n→ Coordination avec Paris MOU\n→ Campagnes de sensibilisation régionales\n\nÉTATS MEMBRES :\nJapon · Chine · Corée · Australie\nRussie · Singapore · Malaisie...",en:"Founded 1993 · Headquarters: Tokyo\nSecond most important MOU globally\n\nSPECIFICS:\n→ Database APCIS\n→ Covers world's largest maritime traffic\n→ Malacca Straits · China Sea\n→ Coordination with Paris MOU\n→ Regional awareness campaigns\n\nMEMBER STATES:\nJapan · China · Korea · Australia\nRussia · Singapore · Malaysia...",es:"Fundado en 1993 · Sede: Tokio\nSegundo MOU en importancia mundial\n\nESPECIFICIDADES:\n→ Base de datos APCIS\n→ Cubre el mayor tráfico marítimo mundial\n→ Estrechos de Malaca · Mar de China\n→ Coordinación con Paris MOU\n\nESTADOS MIEMBROS:\nJapón · China · Corea · Australia\nRusia · Singapur · Malasia...",pt:"Fundado em 1993 · Sede: Tóquio\nSegundo MOU em importância mundial\n\nESPECIFICIDADES:\n→ Base de dados APCIS\n→ Cobre o maior tráfego marítimo mundial\n→ Estreitos de Malaca · Mar da China\n→ Coordenação com o Paris MOU\n\nESTADOS MEMBROS:\nJapão · China · Coreia · Austrália\nRússia · Singapura · Malásia..."}},
    { id:"us_canada", icon:"🇺🇸", color:C.green,
      label:{fr:"USCG (USA/Canada)",en:"USCG (USA/Canada)",es:"USCG (EE.UU./Canadá)",pt:"USCG (EUA/Canadá)"},
      zone:{fr:"Amérique du Nord",en:"North America",es:"América del Norte",pt:"América do Norte"},
      members:{fr:"2 États (USA + Canada)",en:"2 states (USA + Canada)",es:"2 Estados (EE.UU. + Canadá)",pt:"2 estados (EUA + Canadá)"},
      desc:{fr:"USCG = US Coast Guard\nPouvoirs les plus étendus au monde\n\nSPÉCIFICITÉS USA :\n→ Amendes ILLIMITÉES\n→ Prison pour les officiers\n→ Programme whistleblower\n→ Inspection 100% navires à haut risque\n→ Portée : 200 milles nautiques\n→ QUALSHIP 21 : programme qualité\n\nEFFET EXTRATERRITORIAL :\nUSCG peut poursuivre violations MARPOL\ncommises en dehors des eaux US si\nle navire entre dans un port américain",en:"USCG = US Coast Guard\nMost extensive powers in the world\n\nUS SPECIFICS:\n→ UNLIMITED fines\n→ Prison for officers\n→ Whistleblower program\n→ 100% inspection of high-risk vessels\n→ Reach: 200 nautical miles\n→ QUALSHIP 21: quality program\n\nEXTRATERRITORIAL EFFECT:\nUSCG can prosecute MARPOL violations\ncommitted outside US waters if\nvessel enters a US port",es:"USCG = US Coast Guard\nLos poderes más amplios del mundo\n\nESPECIFICIDADES EE.UU.:\n→ Multas ILIMITADAS\n→ Prisión para los oficiales\n→ Programa whistleblower\n→ Inspección 100% buques de alto riesgo\n→ Alcance: 200 millas náuticas\n→ QUALSHIP 21: programa de calidad\n\nEFECTO EXTRATERRITORIAL:\nUSCG puede enjuiciar infracciones MARPOL\ncometidas fuera de aguas americanas si\nel buque entra en un puerto americano",pt:"USCG = US Coast Guard\nOs poderes mais alargados do mundo\n\nESPECIFICIDADES EUA:\n→ Multas ILIMITADAS\n→ Prisão para os oficiais\n→ Programa whistleblower\n→ Inspeção 100% navios de alto risco\n→ Alcance: 200 milhas náuticas\n→ QUALSHIP 21: programa de qualidade\n\nEFEITO EXTRATERRITORIAL:\nUSCG pode processar violações MARPOL\ncometidas fora das águas americanas se\no navio entrar num porto americano"}},
    { id:"others", icon:"🌍", color:C.purple,
      label:{fr:"Autres MOU",en:"Other MOU",es:"Otros MOU",pt:"Outros MOU"},
      zone:{fr:"Mondial",en:"Global",es:"Mundial",pt:"Mundial"},
      members:{fr:"100+ États au total",en:"100+ states total",es:"100+ Estados en total",pt:"100+ estados no total"},
      desc:{fr:"AUTRES ORGANISATIONS PSC :\n\nBlack Sea MOU → Mer Noire (6 États)\nMediterranean MOU → Méditerranée (11 États)\nIndian Ocean MOU → Océan Indien (17 États)\nAbuja MOU → Afrique de l'Ouest (22 États)\nCaribbean MOU → Caraïbes (28 États)\nViña del Mar → Amérique du Sud (16 États)\nRiyadh MOU → Golfe Persique (6 États)\n\nCOORDINATION MONDIALE :\nTous partagent les informations\nBase de données interconnectées\nNavire blacklisté = inspecté partout",en:"OTHER PSC ORGANIZATIONS:\n\nBlack Sea MOU → Black Sea (6 states)\nMediterranean MOU → Mediterranean (11 states)\nIndian Ocean MOU → Indian Ocean (17 states)\nAbuja MOU → West Africa (22 states)\nCaribbean MOU → Caribbean (28 states)\nViña del Mar → South America (16 states)\nRiyadh MOU → Persian Gulf (6 states)\n\nGLOBAL COORDINATION:\nAll share information\nInterconnected databases\nBlacklisted vessel = inspected everywhere",es:"OTRAS ORGANIZACIONES PSC:\n\nBlack Sea MOU → Mar Negro (6 Estados)\nMediterranean MOU → Mediterráneo (11 Estados)\nIndian Ocean MOU → Océano Índico (17 Estados)\nAbuja MOU → África Occidental (22 Estados)\nCaribbean MOU → Caribe (28 Estados)\nViña del Mar → América del Sur (16 Estados)\nRiyadh MOU → Golfo Pérsico (6 Estados)\n\nCOORDINACIÓN MUNDIAL:\nTodos comparten información\nBases de datos interconectadas\nBuque en lista negra = inspeccionado en todas partes",pt:"OUTRAS ORGANIZAÇÕES PSC:\n\nBlack Sea MOU → Mar Negro (6 estados)\nMediterranean MOU → Mediterrâneo (11 estados)\nIndian Ocean MOU → Oceano Índico (17 estados)\nAbuja MOU → África Ocidental (22 estados)\nCaribbean MOU → Caraíbas (28 estados)\nViña del Mar → América do Sul (16 estados)\nRiyadh MOU → Golfo Pérsico (6 estados)\n\nCOORDENAÇÃO MUNDIAL:\nTodos partilham informações\nBases de dados interligadas\nNavio na lista negra = inspecionado em todo o lado"},},
  ];
  const sel_ = sel!==null ? mous[sel] : null;
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
        {mous.map((m,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)}
            style={{padding:"10px 6px",borderRadius:12,cursor:"pointer",textAlign:"center",
              background:sel===i?`${m.color}22`:"rgba(255,255,255,0.04)",
              border:`1.5px solid ${sel===i?m.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:22,marginBottom:3}}>{m.icon}</div>
            <div style={{fontSize:9,color:sel===i?m.color:C.muted,fontWeight:700}}>{m.label[lang]||m.label.fr}</div>
            <div style={{fontSize:7,color:m.color,marginTop:2}}>{m.zone[lang]||m.zone.fr}</div>
            <div style={{fontSize:7,color:C.muted,marginTop:1}}>{m.members[lang]||m.members.fr}</div>
          </div>
        ))}
      </div>
      {sel_&&<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}12`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:sel_.color,marginBottom:2}}>{sel_.icon} {sel_.label[lang]||sel_.label.fr}</div>
        <div style={{fontSize:10,color:sel_.color,marginBottom:6}}>{sel_.zone[lang]||sel_.zone.fr} · {sel_.members[lang]||sel_.members.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{sel_.desc[lang]||sel_.desc.fr}</div>
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// SVG 3 — PORT ACTORS
// ══════════════════════════════════════
function PortActorsSVG({ lang }) {
  const [sel, setSel] = useState(null);
  const actors = [
    { id:"authority", icon:"🏛️", color:C.blue2,
      label:{fr:"Autorité portuaire",en:"Port Authority",es:"Autoridad portuaria",pt:"Autoridade portuária"},
      desc:{fr:"RÔLE :\nGère l'infrastructure portuaire\nFixe les droits de port (port dues)\nRéglemente l'accès au port\nCooronne les escales\n\nPOUVOIRS :\n→ Refus d'accès au port (conditions)\n→ Obligation de pilotage\n→ Redevances portuaires\n→ Gestion des postes à quai\n→ Réglementation environnementale locale\n\nBASE LÉGALE :\nDroit national · règlements portuaires\nConvention FAL (facilitation trafic maritime)",en:"ROLE:\nManages port infrastructure\nSets port dues\nRegulates port access\nCoordinates port calls\n\nPOWERS:\n→ Denial of port access (conditions)\n→ Mandatory pilotage\n→ Port dues\n→ Berth allocation management\n→ Local environmental regulation\n\nLEGAL BASIS:\nNational law · port regulations\nFAL Convention (facilitation of maritime traffic)",es:"FUNCIÓN:\nGestiona la infraestructura portuaria\nFija los derechos portuarios\nRegula el acceso al puerto\nCoorona las escalas\n\nPODERES:\n→ Denegación de acceso al puerto (condiciones)\n→ Prácticaje obligatorio\n→ Tasas portuarias\n→ Gestión de puestos de atraque\n→ Reglamentación medioambiental local",pt:"FUNÇÃO:\nGere a infraestrutura portuária\nFixa as taxas portuárias\nRegula o acesso ao porto\nCoordenação das escalas\n\nPODERES:\n→ Recusa de acesso ao porto (condições)\n→ Praticagem obrigatória\n→ Taxas portuárias\n→ Gestão dos postos de atracação\n→ Regulamentação ambiental local"}},
    { id:"pilot", icon:"🧭", color:C.orange,
      label:{fr:"Pilote maritime",en:"Maritime pilot",es:"Práctico marítimo",pt:"Prático marítimo"},
      desc:{fr:"OBLIGATOIRE dans la plupart des ports\n\nRÔLE :\n→ Guide le navire à l'entrée/sortie du port\n→ Expertise locale (courants · hauts-fonds)\n→ Conseiller du capitaine (pas commandant)\n→ Responsabilité partagée avec le capitaine\n\nSTATUT JURIDIQUE :\nCapitaine reste responsable de son navire\nMême avec pilote à bord\nPilote = conseiller technique\n\nRESPONSABILITÉ PILOTE :\nErreur de pilotage = indemnisation possible\nMais souvent limitée par la loi nationale",en:"MANDATORY in most ports\n\nROLE:\n→ Guides vessel into/out of port\n→ Local expertise (currents · shoals)\n→ Captain's advisor (not commander)\n→ Shared responsibility with captain\n\nLEGAL STATUS:\nCaptain remains responsible for their vessel\nEven with pilot on board\nPilot = technical advisor\n\nPILOT LIABILITY:\nPilotage error = possible compensation\nBut often limited by national law",es:"OBLIGATORIO en la mayoría de los puertos\n\nFUNCIÓN:\n→ Guía el buque en la entrada/salida del puerto\n→ Experiencia local (corrientes · bajos fondos)\n→ Consejero del capitán (no comandante)\n→ Responsabilidad compartida con el capitán\n\nESTATUS JURÍDICO:\nEl capitán sigue siendo responsable de su buque\nIncluso con práctico a bordo\nPráctico = asesor técnico",pt:"OBRIGATÓRIO na maioria dos portos\n\nFUNÇÃO:\n→ Guia o navio na entrada/saída do porto\n→ Conhecimento local (correntes · baixios)\n→ Conselheiro do capitão (não comandante)\n→ Responsabilidade partilhada com o capitão\n\nESTATUTO JURÍDICO:\nO capitão continua a ser responsável pelo seu navio\nMesmo com prático a bordo\nPrático = conselheiro técnico"}},
    { id:"customs", icon:"🔍", color:C.green,
      label:{fr:"Douanes & Immigration",en:"Customs & Immigration",es:"Aduanas e Inmigración",pt:"Alfândega e Imigração"},
      desc:{fr:"CONTRÔLES À L'ARRIVÉE :\nManifeste de cargaison · liste équipage\nPasseports · visas équipage\nDéclaration marchandises\nInspection sanitaire\n\nCONVENTION FAL OMI :\nFacilitation du trafic maritime\nSimplification des formalités douanières\nFormulaires standardisés\nDéclaration électronique obligatoire\n\nDROITS DES DOUANES :\n→ Fouille du navire\n→ Saisie de marchandises illicites\n→ Retenue de l'équipage si infraction",en:"ARRIVAL CONTROLS:\nCargo manifest · crew list\nPassports · crew visas\nGoods declaration\nSanitary inspection\n\nIMO FAL CONVENTION:\nFacilitation of maritime traffic\nSimplification of customs formalities\nStandardized forms\nMandatory electronic declaration\n\nCUSTOMS RIGHTS:\n→ Vessel search\n→ Seizure of illicit goods\n→ Crew detention if violation",es:"CONTROLES A LA LLEGADA:\nManifiesto de carga · lista tripulación\nPasaportes · visas tripulación\nDeclaración de mercancías\nInspección sanitaria\n\nCONVENIO FAL OMI:\nFacilitación del tráfico marítimo\nSimplificación de formalidades aduaneras\nFormularios normalizados\nDeclaración electrónica obligatoria\n\nDERECHOS ADUANEROS:\n→ Registro del buque\n→ Incautación de mercancías ilícitas\n→ Retención de la tripulación si hay infracción",pt:"CONTROLOS À CHEGADA:\nManifesto de carga · lista tripulação\nPassaportes · vistos tripulação\nDeclaração de mercadorias\nInspeção sanitária\n\nCONVENÇÃO FAL IMO:\nFacilitação do tráfego marítimo\nSimplificação das formalidades aduaneiras\nFormulários normalizados\nDeclaração eletrónica obrigatória\n\nDIREITOS ALFANDEGÁRIOS:\n→ Busca do navio\n→ Apreensão de mercadorias ilícitas\n→ Retenção da tripulação se infração"}},
    { id:"psc_port", icon:"🔎", color:C.red,
      label:{fr:"Inspecteur PSC",en:"PSC Inspector",es:"Inspector PSC",pt:"Inspetor PSC"},
      desc:{fr:"AUTORITÉ DE CONTRÔLE DU PORT :\nFonctionnaire de l'État portuaire\nFormé selon normes IMO/MOU\n\nPOUVOIRS :\n→ Monter à bord SANS préavis\n→ Inspecter tous les documents\n→ Tester les équipements de sécurité\n→ Interroger l'équipage\n→ Émettre des déficiences\n→ DÉTENIR le navire si nécessaire\n→ Refuser le départ\n\nINMUNITÉ DE DÉTENTION :\nSi inspection de bonne foi → immunité\nSi faute grave → responsabilité de l'État",en:"PORT STATE CONTROL AUTHORITY:\nPort state government official\nTrained to IMO/MOU standards\n\nPOWERS:\n→ Board vessel WITHOUT prior notice\n→ Inspect all documents\n→ Test safety equipment\n→ Interview crew\n→ Issue deficiencies\n→ DETAIN vessel if necessary\n→ Refuse departure\n\nDETENTION IMMUNITY:\nIf good faith inspection → immunity\nIf serious fault → state liability",es:"AUTORIDAD DE CONTROL DEL PUERTO:\nFuncionario del Estado rector del puerto\nFormado según normas OMI/MOU\n\nPODERES:\n→ Abordar el buque SIN previo aviso\n→ Inspeccionar todos los documentos\n→ Probar los equipos de seguridad\n→ Interrogar a la tripulación\n→ Emitir deficiencias\n→ RETENER el buque si es necesario\n→ Denegar la salida\n\nINMUNIDAD DE RETENCIÓN:\nSi inspección de buena fe → inmunidad\nSi falta grave → responsabilidad del Estado",pt:"AUTORIDADE DE CONTROLO DO PORTO:\nFuncionário do Estado do porto\nFormado de acordo com normas IMO/MOU\n\nPODERES:\n→ Embarcar no navio SEM aviso prévio\n→ Inspecionar todos os documentos\n→ Testar os equipamentos de segurança\n→ Interrogar a tripulação\n→ Emitir deficiências\n→ RETER o navio se necessário\n→ Recusar a partida\n\nIMUNIDADE DE RETENÇÃO:\nSe inspeção de boa fé → imunidade\nSe falta grave → responsabilidade do Estado"},},
  ];
  const sel_ = sel!==null ? actors[sel] : null;
  return (
    <div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
        {actors.map((a,i)=>(
          <div key={i} onClick={()=>setSel(sel===i?null:i)}
            style={{padding:"10px 6px",borderRadius:12,cursor:"pointer",textAlign:"center",
              background:sel===i?`${a.color}22`:"rgba(255,255,255,0.04)",
              border:`1.5px solid ${sel===i?a.color:"rgba(255,255,255,0.08)"}`}}>
            <div style={{fontSize:22,marginBottom:3}}>{a.icon}</div>
            <div style={{fontSize:9,color:sel===i?a.color:C.muted,fontWeight:700,lineHeight:1.3}}>{a.label[lang]||a.label.fr}</div>
          </div>
        ))}
      </div>
      {sel_&&<div style={{padding:"12px",borderRadius:14,background:`${sel_.color}12`,border:`1.5px solid ${sel_.color}44`,animation:"fadeUp 0.3s ease"}}>
        <div style={{fontSize:13,fontWeight:700,color:sel_.color,marginBottom:6}}>{sel_.icon} {sel_.label[lang]||sel_.label.fr}</div>
        <div style={{fontSize:11,color:C.white,lineHeight:1.6,whiteSpace:"pre-line"}}>{sel_.desc[lang]||sel_.desc.fr}</div>
      </div>}
    </div>
  );
}

// ══════════════════════════════════════
// SVG 4 — PSC TARGETING SYSTEM
// ══════════════════════════════════════
function PSCTargetingSVG({ lang }) {
  const [vessel, setVessel] = useState({ age:15, flag:"orange", deficiencies:2, type:"tanker" });
  const calcRisk = () => {
    let score = 0;
    if(vessel.age > 20) score += 3;
    else if(vessel.age > 12) score += 2;
    else score += 1;
    if(vessel.flag === "black") score += 4;
    else if(vessel.flag === "grey") score += 2;
    else score += 0;
    if(vessel.deficiencies > 3) score += 3;
    else if(vessel.deficiencies > 1) score += 2;
    else score += 0;
    if(vessel.type === "tanker" || vessel.type === "bulk") score += 1;
    return score;
  };
  const risk = calcRisk();
  const riskLabel = risk >= 8 ? "HIGH" : risk >= 5 ? "STANDARD" : "LOW";
  const riskColor = risk >= 8 ? C.red : risk >= 5 ? C.orange : C.green;
  const inspection = risk >= 8 ? 100 : risk >= 5 ? 60 : 25;

  return (
    <div>
      <div style={{marginBottom:10,fontSize:10,color:C.muted,textAlign:"center"}}>
        {lang==="fr"?"Paramètres du navire → Calcul du risque PSC":lang==="en"?"Vessel parameters → PSC risk calculation":lang==="es"?"Parámetros del buque → Cálculo de riesgo PSC":"Parâmetros do navio → Cálculo do risco PSC"}
      </div>
      {/* Age */}
      <div style={{marginBottom:10}}>
        <div style={{display:"flex",justifyContent:"space-between",fontSize:10,marginBottom:3}}>
          <span style={{color:C.muted}}>{lang==="fr"?"Âge du navire:":lang==="en"?"Vessel age:":lang==="es"?"Edad del buque:":"Idade do navio:"}</span>
          <span style={{color:C.gold2,fontWeight:700}}>{vessel.age} {lang==="fr"?"ans":"years"}</span>
        </div>
        <input type="range" min={1} max={40} value={vessel.age}
          onChange={e=>setVessel(v=>({...v,age:Number(e.target.value)}))}
          style={{width:"100%",accentColor:C.gold2}}/>
      </div>
      {/* Flag */}
      <div style={{marginBottom:10}}>
        <div style={{fontSize:10,color:C.muted,marginBottom:4}}>{lang==="fr"?"Pavillon:":lang==="en"?"Flag:":lang==="es"?"Pabellón:":"Bandeira:"}</div>
        <div style={{display:"flex",gap:6}}>
          {[["white","⬜","Paris MOU White List"],[" grey","🔲","Paris MOU Grey List"],["orange","🟧","Open Registry"],["black","⬛","Paris MOU Black List"]].map(([val,icon,lbl])=>(
            <button key={val} onClick={()=>setVessel(v=>({...v,flag:val.trim()}))}
              style={{flex:1,padding:"5px 2px",borderRadius:8,cursor:"pointer",textAlign:"center",
                background:vessel.flag===val.trim()?"rgba(255,255,255,0.15)":"rgba(255,255,255,0.04)",
                border:`1.5px solid ${vessel.flag===val.trim()?"rgba(255,255,255,0.5)":"rgba(255,255,255,0.08)"}`,
                fontSize:8,color:C.muted}}>
              <div style={{fontSize:14}}>{icon}</div>
              <div style={{lineHeight:1.2,marginTop:2}}>{lbl.split(' ').slice(0,2).join(' ')}</div>
            </button>
          ))}
        </div>
      </div>
      {/* Deficiencies */}
      <div style={{marginBottom:10}}>
        <div style={{display:"flex",justifyContent:"space-between",fontSize:10,marginBottom:3}}>
          <span style={{color:C.muted}}>{lang==="fr"?"Déficiences historiques:":lang==="en"?"Historical deficiencies:":lang==="es"?"Deficiencias históricas:":"Deficiências históricas:"}</span>
          <span style={{color:C.red,fontWeight:700}}>{vessel.deficiencies}</span>
        </div>
        <input type="range" min={0} max={10} value={vessel.deficiencies}
          onChange={e=>setVessel(v=>({...v,deficiencies:Number(e.target.value)}))}
          style={{width:"100%",accentColor:C.red}}/>
      </div>
      {/* Result */}
      <div style={{padding:"12px",borderRadius:14,background:`${riskColor}12`,border:`1.5px solid ${riskColor}44`,textAlign:"center"}}>
        <div style={{fontSize:11,color:C.muted,marginBottom:4}}>
          {lang==="fr"?"NIVEAU DE RISQUE PSC":lang==="en"?"PSC RISK LEVEL":lang==="es"?"NIVEL DE RIESGO PSC":"NÍVEL DE RISCO PSC"}
        </div>
        <div style={{fontSize:22,fontWeight:700,color:riskColor,fontFamily:"'Cinzel',serif",marginBottom:4}}>{riskLabel}</div>
        <div style={{fontSize:12,color:riskColor}}>
          {lang==="fr"?`Probabilité d'inspection : ${inspection}%`:lang==="en"?`Inspection probability: ${inspection}%`:`Probabilidad de inspección: ${inspection}%`}
        </div>
        <div style={{height:6,borderRadius:3,background:"rgba(255,255,255,0.1)",margin:"8px 0",overflow:"hidden"}}>
          <div style={{height:"100%",width:`${inspection}%`,background:riskColor,transition:"width 0.4s"}}/>
        </div>
        <div style={{fontSize:9,color:C.muted}}>
          {risk>=8?(lang==="fr"?"🔴 CIBLÉ PRIORITAIRE — Inspection quasi-certaine à chaque escale":lang==="en"?"🔴 PRIORITY TARGET — Inspection near-certain at every call":lang==="es"?"🔴 OBJETIVO PRIORITARIO — Inspección casi segura en cada escala":"🔴 ALVO PRIORITÁRIO — Inspeção quase certa em cada escala")
          :risk>=5?(lang==="fr"?"🟡 CIBLAGE STANDARD — Sélectionné périodiquement":lang==="en"?"🟡 STANDARD TARGETING — Selected periodically":lang==="es"?"🟡 SELECCIÓN ESTÁNDAR — Seleccionado periódicamente":"🟡 SELEÇÃO PADRÃO — Selecionado periodicamente")
          :(lang==="fr"?"🟢 FAIBLE RISQUE — Inspecté moins fréquemment":lang==="en"?"🟢 LOW RISK — Inspected less frequently":lang==="es"?"🟢 BAJO RIESGO — Inspeccionado menos frecuentemente":"🟢 BAIXO RISCO — Inspecionado com menos frequência")}
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════
// ACCIDENT CASE
// ══════════════════════════════════════
function AccidentCase({ lang }) {
  const [exp,setExp]=useState(false);
  const d={
    fr:{title:"Affaire MV Prestige — Espagne/France (2002)",teaser:"Pétrolier · 77 000 tonnes HFO · Refus d'accès aux ports · Catastrophe écologique · Polémique juridique",what:"Le pétrolier MV Prestige se retrouve en détresse au large de la Galice (Espagne) le 13 novembre 2002 avec une voie d'eau. Il demande à entrer dans un port de refuge espagnol pour être stabilisé. L'Espagne refuse. Il demande alors refuge au Portugal, qui refuse également. La France aussi refuse. Le navire continue à dériver pendant 6 jours jusqu'à se briser en deux et couler, déversant 77 000 tonnes d'HFO.",cause:"• Refus d'accès aux ports de refuge = décision politique\n• Navire vétuste (26 ans) sous pavillon de complaisance (Bahamas)\n• Absence de règles internationales sur les ports de refuge\n• Chaque État a refusé par crainte d'une catastrophe écologique locale\n• Paradoxe : le refus a causé une catastrophe BIEN plus grave\n• Classification RINA avait accordé des certificats douteux",lessons:"✓ Catastrophe majeure : 400+ km de côtes polluées (Espagne + France + Portugal)\n✓ Coût total : €4 milliards\n✓ Résultat juridique : paquet Prestige (Erika III) en UE\n✓ Adoption des directives ports de refuge UE\n✓ Renforcement SOLAS pour les pétroliers à simple coque\n✓ Interdiction des pétroliers à simple coque dans UE (accélérée)\n✓ BILAN : les États auraient dû accepter le refuge",link:"🔗 Lien L8 : L'affaire Prestige pose la question fondamentale des ports de refuge. Quand un navire est en détresse, qui a le droit/devoir de l'accueillir ? UNCLOS Art.98 = obligation d'assistance aux personnes. Mais aucune obligation formelle d'accorder un port de refuge. Le droit international reste lacunaire sur ce point."},
    en:{title:"MV Prestige Affair — Spain/France (2002)",teaser:"Tanker · 77,000 tonnes HFO · Port access refusals · Ecological disaster · Legal controversy",what:"The tanker MV Prestige is in distress off Galicia (Spain) on November 13, 2002 with a hull breach. It requests entry to a Spanish port of refuge for stabilization. Spain refuses. It then requests refuge in Portugal, which also refuses. France refuses too. The vessel continues drifting for 6 days until it breaks in two and sinks, spilling 77,000 tonnes of HFO.",cause:"• Refusal of port of refuge access = political decision\n• Aging vessel (26 years) under flag of convenience (Bahamas)\n• No international rules on places of refuge\n• Each state refused for fear of local ecological disaster\n• Paradox: the refusal caused a FAR worse disaster\n• RINA classification had issued questionable certificates",lessons:"✓ Major disaster: 400+ km of coastline polluted (Spain + France + Portugal)\n✓ Total cost: €4 billion\n✓ Legal result: Prestige package (Erika III) in EU\n✓ Adoption of EU places of refuge directives\n✓ SOLAS strengthening for single-hull tankers\n✓ Ban on single-hull tankers in EU (accelerated)\n✓ CONCLUSION: states should have granted refuge",link:"🔗 L8 Link: The Prestige affair raises the fundamental question of places of refuge. When a vessel is in distress, who has the right/duty to receive it? UNCLOS Art.98 = obligation to assist persons. But no formal obligation to grant a place of refuge. International law remains incomplete on this point."},
    es:{title:"Caso MV Prestige — España/Francia (2002)",teaser:"Petrolero · 77.000 toneladas HFO · Denegación de acceso a puertos · Catástrofe ecológica · Polémica jurídica",what:"El petrolero MV Prestige se encuentra en apuros frente a Galicia (España) el 13 de noviembre de 2002 con una vía de agua. Solicita entrar en un puerto de refugio español para ser estabilizado. España se niega. Solicita entonces refugio a Portugal, que también se niega. Francia también se niega. El buque sigue a la deriva durante 6 días hasta partirse en dos y hundirse, derramando 77.000 toneladas de HFO.",cause:"• Denegación de acceso a puertos de refugio = decisión política\n• Buque vetusto (26 años) bajo pabellón de conveniencia (Bahamas)\n• Ausencia de normas internacionales sobre puertos de refugio\n• Cada Estado se negó por temor a una catástrofe ecológica local\n• Paradoja: la negativa causó una catástrofe MUCHO más grave",lessons:"✓ Catástrofe mayor: +400 km de costas contaminadas\n✓ Coste total: €4.000 millones\n✓ Resultado jurídico: paquete Prestige (Erika III) en la UE\n✓ Adopción de las directivas de lugares de refugio de la UE\n✓ Refuerzo del SOLAS para los petroleros de casco simple",link:"🔗 Vínculo L8: El caso Prestige plantea la cuestión fundamental de los puertos de refugio. Cuando un buque está en peligro, ¿quién tiene el derecho/deber de acogerlo? El derecho internacional sigue siendo incompleto en este punto."},
    pt:{title:"Caso MV Prestige — Espanha/França (2002)",teaser:"Petroleiro · 77.000 toneladas HFO · Recusa de acesso a portos · Catástrofe ecológica · Polémica jurídica",what:"O petroleiro MV Prestige está em perigo ao largo da Galiza (Espanha) a 13 de novembro de 2002 com uma avaria no casco. Solicita entrada num porto de refúgio espanhol para ser estabilizado. A Espanha recusa. Solicita então refúgio a Portugal, que também recusa. A França também recusa. O navio continua à deriva durante 6 dias até se partir em dois e afundar, derramando 77.000 toneladas de HFO.",cause:"• Recusa de acesso a portos de refúgio = decisão política\n• Navio velho (26 anos) sob bandeira de conveniência (Bahamas)\n• Ausência de regras internacionais sobre portos de refúgio\n• Cada estado recusou por medo de catástrofe ecológica local\n• Paradoxo: a recusa causou uma catástrofe MUITO maior",lessons:"✓ Catástrofe maior: +400 km de costas poluídas\n✓ Custo total: €4 mil milhões\n✓ Resultado jurídico: pacote Prestige (Erika III) na UE\n✓ Adoção das diretivas de locais de refúgio da UE\n✓ Reforço SOLAS para os petroleiros de casco simples",link:"🔗 Vínculo L8: O caso Prestige levanta a questão fundamental dos portos de refúgio. Quando um navio está em perigo, quem tem o direito/dever de o receber? O direito internacional permanece incompleto neste ponto."},
  };
  const c=d[lang]||d.fr;
  return(
    <div style={{background:"rgba(230,126,34,0.08)",border:`1.5px solid ${C.orange}44`,borderRadius:18,overflow:"hidden"}}>
      <div style={{padding:"14px 16px",cursor:"pointer"}} onClick={()=>setExp(v=>!v)}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          <span style={{fontSize:22}}>🛢️</span>
          <div style={{flex:1}}><div style={{fontSize:13,fontWeight:700,color:C.orange,marginBottom:2}}>{c.title}</div><div style={{fontSize:11,color:C.muted,lineHeight:1.4}}>{c.teaser}</div></div>
          <span style={{fontSize:14,color:C.muted}}>{exp?"▲":"▼"}</span>
        </div>
      </div>
      {exp&&<div style={{padding:"0 16px 16px"}}>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,marginBottom:10}}>{c.what}</div>
        <div style={{fontSize:11,color:C.red,fontWeight:700,marginBottom:5,fontFamily:"'Cinzel',serif"}}>CAUSES</div>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,whiteSpace:"pre-line",marginBottom:10}}>{c.cause}</div>
        <div style={{fontSize:11,color:C.green,fontWeight:700,marginBottom:5,fontFamily:"'Cinzel',serif"}}>{lang==="fr"?"LEÇONS":lang==="en"?"LESSONS":lang==="es"?"LECCIONES":"LIÇÕES"}</div>
        <div style={{fontSize:12,color:C.white,lineHeight:1.7,whiteSpace:"pre-line",marginBottom:10}}>{c.lessons}</div>
        <div style={{padding:"10px 12px",borderRadius:10,background:"rgba(201,146,42,0.1)",border:`1px solid ${C.gold}33`,fontSize:11,color:C.gold2,lineHeight:1.6}}>{c.link}</div>
      </div>}
    </div>
  );
}

