// EXERCISE
// ══════════════════════════════════════
function Exercise1({ lang, t }) {
  const [ans,setAns]=useState({q1:"",q2:"",q3:""});
  const [showC,setShowC]=useState(false);
  const qs={
    fr:[
      {id:"q1",q:"Paris MOU = organisation PSC pour quelle région ?\n(Répondre : région géographique)",correct:"Europe"},
      {id:"q2",q:"Quel article UNCLOS impose aux États du pavillon d'exercer leur juridiction sur leurs navires ?\n(Répondre : Article ...)",correct:"94"},
      {id:"q3",q:"Dans l'affaire Prestige (2002), pourquoi le naufrage a-t-il été si catastrophique ?\n(Répondre : 1-2 mots)",correct:"refus ports"},
    ],
    en:[
      {id:"q1",q:"Paris MOU = PSC organization for which region?\n(Answer: geographic region)",correct:"Europe"},
      {id:"q2",q:"Which UNCLOS article requires flag states to exercise jurisdiction over their vessels?\n(Answer: Article ...)",correct:"94"},
      {id:"q3",q:"In the Prestige case (2002), why was the sinking so catastrophic?\n(Answer: 1-2 words)",correct:"port refusal"},
    ],
    es:[
      {id:"q1",q:"Paris MOU = organización PSC para qué región?\n(Responder: región geográfica)",correct:"Europa"},
      {id:"q2",q:"¿Qué artículo CONVEMAR obliga a los Estados de pabellón a ejercer jurisdicción sobre sus buques?\n(Responder: Artículo ...)",correct:"94"},
      {id:"q3",q:"En el caso Prestige (2002), ¿por qué el hundimiento fue tan catastrófico?\n(Responder: 1-2 palabras)",correct:"denegación puertos"},
    ],
    pt:[
      {id:"q1",q:"Paris MOU = organização PSC para que região?\n(Responder: região geográfica)",correct:"Europa"},
      {id:"q2",q:"Que artigo UNCLOS obriga os Estados de bandeira a exercer jurisdição sobre os seus navios?\n(Responder: Artigo ...)",correct:"94"},
      {id:"q3",q:"No caso Prestige (2002), por que o naufrágio foi tão catastrófico?\n(Responder: 1-2 palavras)",correct:"recusa portos"},
    ],
  };
  const list=qs[lang]||qs.fr;
  const chk=(q,val)=>{
    const v=val.trim().toLowerCase();
    if(q.id==="q1") return v.includes("europ");
    if(q.id==="q2") return v.includes("94");
    if(q.id==="q3") return v.includes("refus")||v.includes("denegaci")||v.includes("recusa")||v.includes("port");
    return false;
  };
  return(
    <div>
      <div style={{background:"rgba(0,0,0,0.4)",borderRadius:12,padding:"10px 12px",marginBottom:12,border:`1px solid ${C.steel}44`,fontSize:11,color:C.gold2,lineHeight:1.6}}>
        {lang==="fr"?"💡 Rappels : Paris MOU = Europe · UNCLOS Art.94 = obligations État pavillon · Prestige 2002 = refus ports de refuge"
        :lang==="en"?"💡 Reminders: Paris MOU = Europe · UNCLOS Art.94 = flag state obligations · Prestige 2002 = port of refuge refusal"
        :lang==="es"?"💡 Recordatorios: Paris MOU = Europa · CONVEMAR Art.94 = obligaciones Estado pabellón · Prestige 2002 = denegación puertos de refugio"
        :"💡 Lembretes: Paris MOU = Europa · UNCLOS Art.94 = obrigações Estado bandeira · Prestige 2002 = recusa portos de refúgio"}
      </div>
      {list.map((q,i)=>(
        <div key={q.id} style={{marginBottom:12}}>
          <div style={{fontSize:12,color:C.white,marginBottom:6,lineHeight:1.5,whiteSpace:"pre-line",fontWeight:600}}>{i+1}. {q.q}</div>
          <input type="text" value={ans[q.id]} onChange={e=>setAns(a=>({...a,[q.id]:e.target.value}))} placeholder="?"
            style={{width:"100%",padding:"10px",borderRadius:10,background:"rgba(255,255,255,0.07)",border:`1px solid ${showC?(chk(q,ans[q.id])?C.green:C.red):C.border}`,color:C.white,fontSize:14,fontFamily:"monospace",fontWeight:700,textAlign:"center",boxSizing:"border-box"}}/>
          {showC&&<div style={{fontSize:11,marginTop:4,fontWeight:600,color:chk(q,ans[q.id])?C.green:C.red}}>{chk(q,ans[q.id])?"✓":`✗ → ${q.correct}`}</div>}
        </div>
      ))}
      {showC&&<div style={{padding:"12px",borderRadius:12,background:"rgba(30,138,74,0.1)",border:`1px solid ${C.green}44`,fontSize:11,color:C.white,lineHeight:1.7,marginBottom:10}}>
        {lang==="fr"?"✅ Q1: Europe (Paris MOU = organisation régionale PSC · 27 États européens)\n✅ Q2: Article 94 (UNCLOS Art.94 = obligations juridiques de l'État du pavillon)\n✅ Q3: Refus ports de refuge (Espagne + Portugal + France ont tous refusé → naufrage aggravé)"
        :lang==="en"?"✅ Q1: Europe (Paris MOU = regional PSC organization · 27 European states)\n✅ Q2: Article 94 (UNCLOS Art.94 = flag state legal obligations)\n✅ Q3: Port refusal (Spain + Portugal + France all refused → worsened sinking)"
        :"✅ Q1: Europa · Q2: Artículo 94 · Q3: Denegación de puertos de refugio"}
      </div>}
      <button onClick={()=>setShowC(v=>!v)} style={{width:"100%",padding:"11px 0",borderRadius:12,background:showC?"rgba(30,138,74,0.2)":"rgba(201,146,42,0.15)",border:`1px solid ${showC?C.green:C.gold}44`,color:showC?C.green:C.gold2,fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"'Cinzel',serif"}}>
        {showC?t.hideCorr:t.showCorr}
      </button>
    </div>
  );
}

const QUIZ = {
  fr:[
    {q:"Qu'est-ce qu'un pavillon de complaisance (Flag of Convenience) ?",opts:["Un pavillon militaire","Registre ouvert permettant aux armateurs étrangers d'immatriculer leurs navires pour bénéficier de taxes basses, réglementation allégée et équipages de toute nationalité","Un pavillon de compétition","Un pavillon historique"],correct:1,expl:"Pavillon de complaisance = open registry. Les armateurs immatriculent leurs navires dans des États qui ne sont pas leur pays d'origine pour bénéficier : taxes très basses/nulles, équipage de toute nationalité (salaires bas), réglementation moins stricte, immatriculation rapide. 73% de la flotte mondiale navigue sous pavillon de complaisance. Principaux : Panama, Liberia, Marshall Islands, Bahamas."},
    {q:"L'article 94 de l'UNCLOS impose à l'État du pavillon d'exercer quelle obligation principale ?",opts:["Payer les taxes de l'OMI","Exercer sa juridiction et son contrôle effectifs sur les navires battant son pavillon en matière de sécurité, environnement et conditions de travail","Construire des navires","Assurer le pilotage dans les ports"],correct:1,expl:"UNCLOS Article 94 = obligations de l'État du pavillon. Doit : exercer sa juridiction sur ses navires, maintenir un registre, assurer la conformité SOLAS/MARPOL/STCW/MLC, vérifier les qualifications des marins, mener les enquêtes sur les accidents. Si un État ne remplit pas ces obligations : ses navires peuvent être mis sur liste noire PSC, et l'État risque d'être exclu de la whitelist OMI."},
    {q:"Le Paris MOU (Memorandum of Understanding) couvre quelle région géographique ?",opts:["Asie-Pacifique","Amérique du Nord","Europe et Atlantique Nord","Afrique de l'Ouest"],correct:2,expl:"Paris MOU = organisation régionale de Port State Control pour l'Europe et l'Atlantique Nord. Fondé en 1982. 27 États membres. Le plus ancien et le plus strict des MOU. Siège à Paris. Base de données THETIS commune. Publie chaque année les listes blanche (bonne performance), grise (à surveiller) et noire (mauvaise performance) des pavillons. Objectif : inspecter 25% des navires par an dans ses ports."},
    {q:"Dans l'affaire Prestige (2002), pourquoi la catastrophe écologique a-t-elle été si grave ?",opts:["Le navire était trop rapide","L'Espagne, le Portugal et la France ont tous refusé d'accorder un port de refuge, forçant le navire à dériver jusqu'à se briser","L'OMI n'a pas réagi à temps","Le capitaine n'avait pas de certificats STCW"],correct:1,expl:"L'affaire Prestige est l'exemple paradigmatique des lacunes du droit sur les ports de refuge. Le Prestige demandait refuge pour être stabilisé — si un port l'avait accueilli, la catastrophe aurait pu être évitée ou limitée. Le refus de 3 États (Espagne, Portugal, France) par crainte politique a conduit à un naufrage en pleine mer = 77 000 tonnes HFO. Coût final : €4 milliards. Résultat : paquet Prestige (Erika III), directives UE sur ports de refuge."},
    {q:"Un inspecteur PSC a-t-il le droit de monter à bord d'un navire étranger sans préavis ?",opts:["Non — il doit demander l'autorisation au capitaine 24h avant","Oui — l'inspecteur PSC peut monter à bord à tout moment sans autorisation préalable, sur la base du droit international (UNCLOS Art.218)","Non — il doit attendre une plainte de l'équipage","Oui — mais seulement si le navire est sous pavillon de complaisance"],correct:1,expl:"L'inspecteur PSC a le droit de monter à bord SANS préavis (UNCLOS Art.218, Convention SOLAS, MOU régionaux). Peut inspecter : documents, certificats, équipements de sécurité, conditions de vie, journaux de bord. Peut interroger l'équipage. Peut émettre des déficiences. Peut DÉTENIR le navire si nécessaire. Le capitaine ne peut pas refuser l'inspection — refus = aggravation + détention quasi-automatique."},
  ],
  en:[
    {q:"What is a Flag of Convenience?",opts:["A military flag","Open registry allowing foreign shipowners to register their vessels to benefit from low taxes, lighter regulation and crew of any nationality","A competition flag","A historical flag"],correct:1,expl:"Flag of Convenience = open registry. Shipowners register their vessels in states that are not their home country to benefit from: very low/zero taxes, crew of any nationality (low wages), less strict regulation, fast registration. 73% of the world fleet sails under flags of convenience. Main ones: Panama, Liberia, Marshall Islands, Bahamas."},
    {q:"UNCLOS Article 94 imposes on the flag state what main obligation?",opts:["Pay IMO taxes","Effectively exercise jurisdiction and control over vessels flying its flag regarding safety, environment and working conditions","Build vessels","Provide pilotage in ports"],correct:1,expl:"UNCLOS Article 94 = flag state obligations. Must: exercise jurisdiction over its vessels, maintain a register, ensure SOLAS/MARPOL/STCW/MLC compliance, verify seafarer qualifications, conduct accident investigations. If a state fails these obligations: its vessels can be blacklisted by PSC, and state risks exclusion from IMO whitelist."},
    {q:"The Paris MOU covers which geographic region?",opts:["Asia-Pacific","North America","Europe and North Atlantic","West Africa"],correct:2,expl:"Paris MOU = regional Port State Control organization for Europe and the North Atlantic. Founded 1982. 27 member states. Oldest and strictest MOU. Headquarters in Paris. Common THETIS database. Publishes annual white (good performance), grey (under observation) and black (poor performance) flag lists. Target: inspect 25% of vessels per year in its ports."},
    {q:"In the Prestige case (2002), why was the ecological disaster so severe?",opts:["The vessel was too fast","Spain, Portugal and France all refused to grant a place of refuge, forcing the vessel to drift until it broke apart","IMO didn't react in time","The captain had no STCW certificates"],correct:1,expl:"The Prestige case is the paradigmatic example of gaps in law on places of refuge. The Prestige was requesting refuge for stabilization — if a port had received it, the disaster could have been avoided or limited. The refusal by 3 states (Spain, Portugal, France) for political reasons led to a sinking at sea = 77,000 tonnes of HFO. Final cost: €4 billion. Result: Prestige package (Erika III), EU directives on places of refuge."},
    {q:"Can a PSC inspector board a foreign vessel without prior notice?",opts:["No — must ask captain's permission 24h in advance","Yes — PSC inspector can board at any time without prior authorization, based on international law (UNCLOS Art.218)","No — must wait for crew complaint","Yes — but only if vessel is under flag of convenience"],correct:1,expl:"PSC inspector has the right to board WITHOUT prior notice (UNCLOS Art.218, SOLAS Convention, regional MOU). Can inspect: documents, certificates, safety equipment, living conditions, logbooks. Can interview crew. Can issue deficiencies. Can DETAIN vessel if necessary. Captain cannot refuse inspection — refusal = aggravation + near-automatic detention."},
  ],
  es:[
    {q:"¿Qué es un pabellón de conveniencia (Flag of Convenience)?",opts:["Un pabellón militar","Registro abierto que permite a los armadores extranjeros matricular sus buques para beneficiarse de impuestos bajos, reglamentación aligerada y tripulación de cualquier nacionalidad","Un pabellón de competición","Un pabellón histórico"],correct:1,expl:"Pabellón de conveniencia = registro abierto. Los armadores matriculan sus buques en Estados que no son su país de origen para beneficiarse de: impuestos muy bajos/nulos, tripulación de cualquier nacionalidad (salarios bajos), reglamentación menos estricta, matriculación rápida. El 73% de la flota mundial navega bajo pabellón de conveniencia. Principales: Panamá, Liberia, Islas Marshall, Bahamas."},
    {q:"¿El artículo 94 de la CONVEMAR impone al Estado de pabellón qué obligación principal?",opts:["Pagar los impuestos de la OMI","Ejercer su jurisdicción y control efectivos sobre los buques que enarbolan su pabellón en materia de seguridad, medio ambiente y condiciones laborales","Construir buques","Garantizar el practicaje en los puertos"],correct:1,expl:"CONVEMAR Artículo 94 = obligaciones del Estado de pabellón. Debe: ejercer jurisdicción sobre sus buques, mantener un registro, asegurar el cumplimiento de SOLAS/MARPOL/STCW/MLC, verificar las titulaciones de los marinos, realizar investigaciones de accidentes. Si un Estado incumple estas obligaciones: sus buques pueden ser incluidos en la lista negra del PSC y el Estado corre el riesgo de ser excluido de la lista blanca de la OMI."},
    {q:"¿El Paris MOU cubre qué región geográfica?",opts:["Asia-Pacífico","América del Norte","Europa y Atlántico Norte","África Occidental"],correct:2,expl:"Paris MOU = organización regional de PSC para Europa y el Atlántico Norte. Fundado en 1982. 27 Estados miembros. El más antiguo y estricto de los MOU. Sede en París. Base de datos THETIS común. Publica anualmente las listas blanca (buena actuación), gris (bajo observación) y negra (mala actuación) de pabellones. Objetivo: inspeccionar el 25% de los buques al año en sus puertos."},
    {q:"En el caso Prestige (2002), ¿por qué fue tan grave la catástrofe ecológica?",opts:["El buque iba demasiado rápido","España, Portugal y Francia se negaron a conceder un puerto de refugio, forzando al buque a la deriva hasta partirse","La OMI no reaccionó a tiempo","El capitán no tenía certificados STCW"],correct:1,expl:"El caso Prestige es el ejemplo paradigmático de las lagunas del derecho sobre los puertos de refugio. El Prestige solicitaba refugio para ser estabilizado — si un puerto lo hubiera acogido, la catástrofe podría haberse evitado o limitado. La negativa de 3 Estados por razones políticas llevó a un hundimiento en alta mar = 77.000 toneladas de HFO. Coste final: €4.000 millones. Resultado: paquete Prestige (Erika III), directivas UE sobre puertos de refugio."},
    {q:"¿Un inspector PSC tiene derecho a abordar un buque extranjero sin previo aviso?",opts:["No — debe pedir permiso al capitán con 24h de antelación","Sí — el inspector PSC puede abordar en cualquier momento sin autorización previa, basándose en el derecho internacional (CONVEMAR Art.218)","No — debe esperar una queja de la tripulación","Sí — pero solo si el buque está bajo pabellón de conveniencia"],correct:1,expl:"El inspector PSC tiene derecho a abordar SIN previo aviso (CONVEMAR Art.218, Convenio SOLAS, MOU regionales). Puede inspeccionar: documentos, certificados, equipos de seguridad, condiciones de vida, diarios de navegación. Puede interrogar a la tripulación. Puede emitir deficiencias. Puede RETENER el buque si es necesario. El capitán no puede rechazar la inspección — negativa = agravante + retención casi automática."},
  ],
  pt:[
    {q:"O que é uma bandeira de conveniência (Flag of Convenience)?",opts:["Uma bandeira militar","Registo aberto que permite aos armadores estrangeiros registar os seus navios para beneficiar de impostos baixos, regulamentação aliviada e tripulação de qualquer nacionalidade","Uma bandeira de competição","Uma bandeira histórica"],correct:1,expl:"Bandeira de conveniência = registo aberto. Os armadores registam os seus navios em estados que não são o seu país de origem para beneficiar de: impostos muito baixos/nulos, tripulação de qualquer nacionalidade (salários baixos), regulamentação menos rigorosa, registo rápido. 73% da frota mundial navega sob bandeira de conveniência. Principais: Panamá, Libéria, Ilhas Marshall, Bahamas."},
    {q:"O artigo 94 da UNCLOS impõe ao Estado de bandeira que obrigação principal?",opts:["Pagar os impostos da IMO","Exercer efetivamente a sua jurisdição e controlo sobre os navios que arvoram a sua bandeira em matéria de segurança, ambiente e condições de trabalho","Construir navios","Assegurar a praticagem nos portos"],correct:1,expl:"UNCLOS Artigo 94 = obrigações do Estado de bandeira. Deve: exercer jurisdição sobre os seus navios, manter um registo, assegurar conformidade SOLAS/MARPOL/STCW/MLC, verificar as qualificações dos marítimos, conduzir investigações de acidentes. Se um estado não cumprir estas obrigações: os seus navios podem ser incluídos na lista negra do PSC e o estado arrisca exclusão da lista branca da IMO."},
    {q:"O Paris MOU abrange que região geográfica?",opts:["Ásia-Pacífico","América do Norte","Europa e Atlântico Norte","África Ocidental"],correct:2,expl:"Paris MOU = organização regional de Controlo do Estado do Porto para a Europa e Atlântico Norte. Fundado em 1982. 27 estados membros. O mais antigo e rigoroso dos MOU. Sede em Paris. Base de dados THETIS comum. Publica anualmente as listas branca (boa desempenho), cinzenta (sob observação) e negra (mau desempenho) de bandeiras. Objetivo: inspecionar 25% dos navios por ano nos seus portos."},
    {q:"No caso Prestige (2002), por que a catástrofe ecológica foi tão grave?",opts:["O navio ia demasiado rápido","Espanha, Portugal e França recusaram conceder um porto de refúgio, forçando o navio a derivar até se partir","A IMO não reagiu a tempo","O capitão não tinha certificados STCW"],correct:1,expl:"O caso Prestige é o exemplo paradigmático das lacunas do direito sobre os portos de refúgio. O Prestige solicitava refúgio para ser estabilizado — se um porto o tivesse recebido, a catástrofe poderia ter sido evitada ou limitada. A recusa de 3 estados por razões políticas levou a um naufrágio em alto mar = 77.000 toneladas de HFO. Custo final: €4 mil milhões. Resultado: pacote Prestige (Erika III), diretivas UE sobre portos de refúgio."},
    {q:"Um inspetor PSC tem o direito de embarcar num navio estrangeiro sem aviso prévio?",opts:["Não — deve pedir autorização ao capitão 24h antes","Sim — o inspetor PSC pode embarcar a qualquer momento sem autorização prévia, com base no direito internacional (UNCLOS Art.218)","Não — deve aguardar uma queixa da tripulação","Sim — mas apenas se o navio estiver sob bandeira de conveniência"],correct:1,expl:"O inspetor PSC tem o direito de embarcar SEM aviso prévio (UNCLOS Art.218, Convenção SOLAS, MOU regionais). Pode inspecionar: documentos, certificados, equipamentos de segurança, condições de vida, diários de bordo. Pode interrogar a tripulação. Pode emitir deficiências. Pode RETER o navio se necessário. O capitão não pode recusar a inspeção — recusa = agravante + retenção quase automática."},
  ],
};

const BANK = {
  fr:[
    {q:"Qu'est-ce que le 'lien substantiel' (genuine link) entre un navire et son État du pavillon ?",opts:["Un contrat d'assurance","Exigence UNCLOS Art.91 : lien réel et effectif entre l'État du pavillon et le navire — l'État doit effectivement exercer sa juridiction","Un accord commercial","Un certificat de navigabilité"],correct:1,expl:"Genuine link (UNCLOS Art.91) = principe selon lequel il doit exister un lien effectif entre l'État du pavillon et le navire. Théoriquement, un État ne peut pas accorder son pavillon sans avoir un lien réel avec le navire. En pratique : les pavillons de complaisance ont longtemps contourné ce principe. L'OMI a tenté de le renforcer mais sans mécanisme d'exécution clair. Reste une source de débat en droit maritime international."},
    {q:"Qu'est-ce que le 'right to deny port entry' (droit de refus d'accès au port) ?",opts:["Un droit absolu de l'État côtier","Droit de l'État côtier de refuser l'accès à son port à un navire étranger sous certaines conditions — mais avec limites (détresse maritime, UNCLOS)","Un droit commercial du port","Un droit réservé aux États membres OMI"],correct:1,expl:"Droit de refus d'accès au port = droit souverain de l'État côtier. L'État peut refuser l'accès pour : raisons de sécurité, protection environnementale, sanctions internationales. LIMITE IMPORTANTE : si un navire est en détresse (Art.98 UNCLOS, SAR 1979), l'obligation d'assistance peut primer. L'affaire Prestige (2002) a montré les conséquences dramatiques d'un refus de port de refuge en cas de détresse."},
    {q:"Qu'est-ce que la 'QUALSHIP 21' (USCG Quality Shipping for the 21st Century) ?",opts:["Un programme de formation","Programme USCG récompensant les navires ayant un excellent historique PSC — inspection réduite · accès prioritaire aux ports américains","Un certificat de navigabilité","Un programme de l'OMI"],correct:1,expl:"QUALSHIP 21 = programme USCG créé en 2001. Récompense les navires ayant un excellent bilan PSC (0 déficience sur 3 ans d'inspections). Avantages : inspection réduite au minimum, priorité aux postes à quai, reconnaissance officielle. Objectif : encourager les armateurs à maintenir des navires de haute qualité. Équivalent au système de 'pavillon blanc' mais pour les navires individuels."},
    {q:"Qu'est-ce que la 'Convention FAL' de l'OMI ?",opts:["Une convention sur la sécurité des navires","Convention de facilitation du trafic maritime international (1965) — standardise les formalités portuaires pour réduire les délais d'escale","Une convention sur la pollution","Une convention de navigation"],correct:1,expl:"Convention FAL (Facilitation of International Maritime Traffic, 1965) = simplifie et standardise les formalités portuaires. Formulaires standardisés (FAL forms) pour : déclaration générale, liste des personnes à bord, liste des marchandises, déclaration de santé maritime, déclaration de sécurité du navire. Depuis 2017 : déclaration électronique obligatoire (e-FAL). Objectif : réduire les délais et coûts des escales."},
    {q:"Qu'est-ce que le pilotage maritime et sa responsabilité juridique ?",opts:["Un service optionnel","Service de guidage du navire dans les eaux portuaires par un expert local — obligatoire dans la plupart des ports · responsabilité partagée capitaine/pilote","Un service commercial","Un service réservé aux grands navires"],correct:1,expl:"Pilotage maritime = service de guidage dans les eaux portuaires par un expert local. Obligatoire dans la plupart des ports. Statut juridique : le pilote est un conseiller technique mais le CAPITAINE reste commandant et responsable. Si accident avec pilote à bord : responsabilité partagée selon les circonstances. Dans de nombreux pays : responsabilité du pilote limitée par la loi (plafond). Pilote = fonctionnaire ou prestataire selon le système national."},
    {q:"Qu'est-ce que la liste des 'Priority Ships' (navires prioritaires) du Paris MOU ?",opts:["Une liste d'armateurs VIP","Liste des navires ciblés en priorité pour inspection PSC basée sur leur profil de risque (âge, pavillon, historique déficiences)","Une liste de navires militaires","Une liste de navires neufs"],correct:1,expl:"Priority ships = navires ciblés en priorité pour inspection PSC selon leur Target Factor (TF) calculé par le système THETIS. Facteurs : âge du navire, historique de déficiences, performance du pavillon, type de navire, dernier port d'inspection. Navires à haut TF = inspecté à chaque escale. Navires à faible TF = inspecté périodiquement. Système transparent publié sur le site Paris MOU."},
    {q:"Qu'est-ce que la 'blacklist' des pavillons du Paris MOU ?",opts:["Une liste de pirates","Classification annuelle des États du pavillon selon leur taux de détention — liste noire = performance PSC insuffisante · navires inspectés systématiquement","Une liste de ports dangereux","Une liste de navires volés"],correct:1,expl:"Blacklist Paris MOU = liste noire des pavillons publiée annuellement. Classification : Blanche (bonne performance, taux détention < 2%), Grise (performance moyenne, surveillance), Noire (mauvaise performance, taux détention élevé). Si pavillon liste noire : navires de ce pavillon inspectés SYSTÉMATIQUEMENT à chaque escale dans les ports Paris MOU. Pression sur l'État du pavillon pour améliorer ses standards."},
    {q:"Qu'est-ce que le 'shiprider agreement' en droit maritime international ?",opts:["Un accord d'équipage","Accord bilatéral permettant à des agents d'un État d'embarquer sur des navires de patrouille d'un autre État pour exercer une juridiction partagée — anti-drogue · anti-piraterie","Un accord de remorquage","Un accord commercial"],correct:1,expl:"Shiprider agreement = accord bilatéral de droit maritime permettant à des agents (ex : gardes-côtes) d'un État A d'embarquer sur des patrouilleurs de l'État B pour exercer leur juridiction nationale dans les eaux de B. Utilisé principalement dans la lutte contre le trafic de drogues (Caraïbes) et la piraterie (Corne de l'Afrique). Contourne le principe d'exclusivité du pavillon en haute mer."},
    {q:"Qu'est-ce que la 'réglementation d'entrave à la navigation' (COLREG Règle 10 DST) ?",opts:["Une règle météorologique","Réglementation des dispositifs de séparation du trafic dans les ports et approches portuaires — passages obligatoires · couloirs de navigation","Un règlement commercial","Un accord entre armateurs"],correct:1,expl:"DST (Dispositifs de Séparation du Trafic) = COLREG Règle 10. Zones de navigation définie dans les approches portuaires et détroits fréquentés. Navires doivent utiliser les couloirs appropriés. L'État côtier peut établir des DST dans ses eaux. OMI approuve les DST en mer internationale. Non-respect = violation COLREG + responsabilité civile + pénale possible. Vérification par PSC."},
    {q:"Qu'est-ce que l'obligation de 'notification préalable' avant l'entrée dans un port ?",opts:["Une recommandation optionnelle","Obligation légale de notifier le port de destination 24-96h avant l'arrivée — informations transmises : navire, cargaison, équipage, état du navire","Un accord commercial","Une obligation douanière uniquement"],correct:1,expl:"Notification préalable (pre-arrival notification) = obligation réglementaire dans la plupart des États. Délai : 24h minimum (certains ports 48-96h). Informations : nom/pavillon/MMSI, port de provenance, heure d'arrivée estimée, nature de la cargaison, nombre de personnes à bord, état du navire, besoins médicaux. Sert à : PSC ciblage, préparation douanes, gestion portuaire. Règlement EU n°725/2004 + SOLAS V/19.4."},
    {q:"Qu'est-ce que le 'bail out' par l'État du pavillon après un accident maritime ?",opts:["Un secours financier","Obligation de l'État du pavillon de mener une enquête officielle sur les accidents majeurs survenant à ses navires — Résolution OMI A.884(21)","Un type d'assurance","Un accord de sauvetage"],correct:1,expl:"Enquête de l'État du pavillon = obligation UNCLOS + Résolution OMI A.884(21). Après tout accident grave (perte de navire, mort, pollution majeure) : l'État du pavillon DOIT mener une enquête officielle indépendante. Objectif : déterminer les causes, recommander des améliorations, prévenir la récurrence. Rapport envoyé à l'OMI. Si l'État du pavillon ne mène pas l'enquête (pavillons de complaisance défaillants) : l'État côtier concerné peut mener sa propre enquête."},
    {q:"Qu'est-ce que le 'droit de refus de départ' (right to refuse departure) du PSC ?",opts:["Un droit commercial","Droit du PSC de refuser l'autorisation de départ d'un navire jusqu'à correction des déficiences graves — peut durer des jours ou semaines","Un droit militaire","Un droit de l'OMI"],correct:1,expl:"Droit de refus de départ PSC = pouvoir central du PSC. Si déficiences graves détectées → le PSC peut émettre une 'detention order' (ordre de détention). Le navire NE PEUT PAS appareiller jusqu'à : correction des déficiences, ou obtention d'une dérogation. Coûts : frais de port (~€10 000-50 000/jour), perte de fret, pénalités de retard. Appel possible devant le tribunal national."},
    {q:"Qu'est-ce que le 'port state measures agreement' (accord de l'OMI sur les mesures du ressort de l'État du port) ?",opts:["Un accord commercial","Accord OMI (2009) permettant aux États d'inspecter et refuser les navires de pêche INN (pêche illicite non déclarée) dans leurs ports","Un accord de sécurité","Un accord sur le pilotage"],correct:1,expl:"Agreement on Port State Measures (PSMA) 2009 = premier accord international contraignant de l'OMI spécifiquement dédié à la lutte contre la pêche INN (illicite, non déclarée et non réglementée). Permet aux États d'inspecter les navires de pêche dans leurs ports, refuser l'entrée aux navires suspects de pêche INN, partager les informations. En vigueur depuis 2016. Instrument clé pour la gestion durable des océans."},
    {q:"Qu'est-ce que la 'Convention Nairobi' (2007) sur le retrait des épaves ?",opts:["Une convention africaine","Convention internationale (2007, en vigueur 2015) obligeant le propriétaire du navire à retirer les épaves dangereuses et à disposer d'une assurance — applicable dans la ZEE","Une convention de pêche","Un accord portuaire"],correct:1,expl:"Convention de Nairobi sur le retrait des épaves (2007, en vigueur 2015) = comble une lacune entre UNCLOS et le droit national. Applicable dans la ZEE (et volontairement dans les eaux territoriales). Oblige le propriétaire à : signaler rapidement l'épave, évaluer le risque, prendre des mesures, retirer l'épave si dangereuse. Assurance obligatoire pour les navires > 300 TB. Certificat d'assurance (Wreck Removal Certificate) délivré par l'État du pavillon."},
    {q:"Qu'est-ce que la 'visite de contrôle' (survey) obligatoire pour maintenir les certificats SOLAS ?",opts:["Une visite commerciale","Inspection périodique du navire par un organisme agréé (société de classification ou État du pavillon) pour vérifier la conformité et renouveler les certificats","Une inspection PSC","Une visite douanière"],correct:1,expl:"Survey SOLAS = inspection périodique obligatoire. Certificat de sécurité (5 ans) : survey initial + surveys intermédiaires (2,5 ans) + surveys annuels. Effectuée par : société de classification agréée par l'État du pavillon, ou directement par l'État du pavillon. En cas d'accident majeur : survey spécial requis avant reprise d'activité. Sans survey valide = certificats expirés = PSC peut détenir le navire."},
  ],
  en:[
    {q:"What is the 'genuine link' between a vessel and its flag state?",opts:["An insurance contract","UNCLOS Art.91 requirement: real and effective link between flag state and vessel — state must effectively exercise its jurisdiction","A commercial agreement","A seaworthiness certificate"],correct:1,expl:"Genuine link (UNCLOS Art.91) = principle that there must be an effective link between the flag state and the vessel. Theoretically, a state cannot grant its flag without a real link to the vessel. In practice: flags of convenience have long circumvented this principle. IMO has tried to strengthen it but without a clear enforcement mechanism. Remains a source of debate in international maritime law."},
    {q:"What is the 'right to deny port entry'?",opts:["An absolute right of the coastal state","Right of the coastal state to refuse port access to a foreign vessel under certain conditions — but with limits (maritime distress, UNCLOS)","A commercial port right","A right reserved for IMO member states"],correct:1,expl:"Right to deny port entry = sovereign right of the coastal state. The state can refuse access for: security reasons, environmental protection, international sanctions. IMPORTANT LIMIT: if a vessel is in distress (UNCLOS Art.98, SAR 1979), the duty to assist may take priority. The Prestige case (2002) showed the dramatic consequences of refusing a port of refuge to a vessel in distress."},
    {q:"What is 'QUALSHIP 21' (USCG Quality Shipping for the 21st Century)?",opts:["A training program","USCG program rewarding vessels with excellent PSC record — reduced inspection · priority access to US ports","A seaworthiness certificate","An IMO program"],correct:1,expl:"QUALSHIP 21 = USCG program created in 2001. Rewards vessels with excellent PSC record (0 deficiencies over 3 years of inspections). Benefits: minimum inspection, priority berths, official recognition. Objective: encourage shipowners to maintain high-quality vessels. Equivalent to 'white flag' system but for individual vessels."},
    {q:"What is the IMO 'FAL Convention'?",opts:["A vessel safety convention","Convention on Facilitation of International Maritime Traffic (1965) — standardizes port formalities to reduce port call delays","A pollution convention","A navigation convention"],correct:1,expl:"FAL Convention (Facilitation of International Maritime Traffic, 1965) = simplifies and standardizes port formalities. Standardized forms (FAL forms) for: general declaration, persons on board list, cargo list, maritime health declaration, ship's security declaration. Since 2017: mandatory electronic declaration (e-FAL). Objective: reduce port call delays and costs."},
    {q:"What is maritime pilotage and its legal liability?",opts:["An optional service","Service guiding vessel through port waters by a local expert — mandatory in most ports · shared liability captain/pilot","A commercial service","A service reserved for large vessels"],correct:1,expl:"Maritime pilotage = guidance service through port waters by local expert. Mandatory in most ports. Legal status: pilot is a technical advisor but CAPTAIN remains in command and responsible. If accident with pilot on board: shared liability depending on circumstances. In many countries: pilot liability limited by law (ceiling). Pilot = civil servant or service provider depending on national system."},
    {q:"What is the Paris MOU 'Priority Ships' list?",opts:["A VIP shipowner list","List of vessels targeted as priority for PSC inspection based on their risk profile (age, flag, deficiency history)","A military vessel list","A list of new vessels"],correct:1,expl:"Priority ships = vessels targeted as priority for PSC inspection according to their Target Factor (TF) calculated by the THETIS system. Factors: vessel age, deficiency history, flag performance, vessel type, last inspection port. High TF vessels = inspected at every call. Low TF vessels = inspected periodically. Transparent system published on Paris MOU website."},
    {q:"What is the Paris MOU flag 'blacklist'?",opts:["A pirate list","Annual classification of flag states by detention rate — black list = insufficient PSC performance · vessels systematically inspected","A list of dangerous ports","A list of stolen vessels"],correct:1,expl:"Paris MOU Blacklist = annual flag blacklist. Classification: White (good performance, detention rate < 2%), Grey (average performance, monitoring), Black (poor performance, high detention rate). If black list flag: vessels of that flag inspected SYSTEMATICALLY at every Paris MOU port call. Pressure on flag state to improve its standards."},
    {q:"What is a 'shiprider agreement' in international maritime law?",opts:["A crew agreement","Bilateral agreement allowing agents of one state to embark on patrol vessels of another state to exercise shared jurisdiction — anti-drug · anti-piracy","A towage agreement","A commercial agreement"],correct:1,expl:"Shiprider agreement = bilateral maritime law agreement allowing agents (e.g. coast guards) of State A to embark on patrol vessels of State B to exercise their national jurisdiction in B's waters. Mainly used in the fight against drug trafficking (Caribbean) and piracy (Horn of Africa). Circumvents the flag exclusivity principle on the high seas."},
    {q:"What is the Traffic Separation Scheme (TSS) regulation (COLREG Rule 10)?",opts:["A weather rule","Regulation of traffic separation schemes in port approaches and straits — mandatory lanes · navigation channels","A commercial regulation","An agreement between shipowners"],correct:1,expl:"TSS (Traffic Separation Scheme) = COLREG Rule 10. Defined navigation zones in port approaches and busy straits. Vessels must use appropriate lanes. Coastal state can establish TSS in its waters. IMO approves TSS in international waters. Non-compliance = COLREG violation + civil liability + possible criminal liability. PSC verification."},
    {q:"What is the 'pre-arrival notification' obligation before entering a port?",opts:["An optional recommendation","Legal obligation to notify destination port 24-96h before arrival — information transmitted: vessel, cargo, crew, vessel condition","A commercial agreement","A customs obligation only"],correct:1,expl:"Pre-arrival notification = regulatory obligation in most states. Deadline: minimum 24h (some ports 48-96h). Information: name/flag/MMSI, port of origin, estimated arrival time, nature of cargo, persons on board, vessel condition, medical needs. Used for: PSC targeting, customs preparation, port management. EU Regulation 725/2004 + SOLAS V/19.4."},
    {q:"What is the flag state 'accident investigation' obligation?",opts:["Financial assistance","Obligation of the flag state to conduct an official investigation into major accidents occurring to its vessels — IMO Resolution A.884(21)","A type of insurance","A salvage agreement"],correct:1,expl:"Flag state investigation = UNCLOS obligation + IMO Resolution A.884(21). After any serious accident (vessel loss, death, major pollution): flag state MUST conduct an independent official investigation. Objective: determine causes, recommend improvements, prevent recurrence. Report sent to IMO. If flag state fails to investigate (deficient flags of convenience): the concerned coastal state can conduct its own investigation."},
    {q:"What is the PSC 'right to refuse departure'?",opts:["A commercial right","PSC right to refuse departure authorization until serious deficiencies are corrected — can last days or weeks","A military right","An IMO right"],correct:1,expl:"PSC right to refuse departure = central PSC power. If serious deficiencies detected → PSC can issue a 'detention order'. Vessel CANNOT depart until: deficiencies corrected, or waiver obtained. Costs: port fees (~€10,000-50,000/day), cargo loss, delay penalties. Appeal possible before national court."},
    {q:"What is the IMO 'Port State Measures Agreement' (PSMA)?",opts:["A commercial agreement","IMO agreement (2009) allowing states to inspect and refuse IUU fishing vessels in their ports (illegal, unreported and unregulated fishing)","A safety agreement","A pilotage agreement"],correct:1,expl:"PSMA (Port State Measures Agreement) 2009 = first binding IMO international agreement specifically dedicated to combating IUU fishing (illegal, unreported and unregulated). Allows states to inspect fishing vessels in their ports, refuse entry to vessels suspected of IUU fishing, share information. In force since 2016. Key instrument for sustainable ocean management."},
    {q:"What is the 'Nairobi Convention' (2007) on wreck removal?",opts:["An African convention","International convention (2007, in force 2015) requiring vessel owner to remove hazardous wrecks and have insurance — applicable in EEZ","A fishing convention","A port agreement"],correct:1,expl:"Nairobi Convention on Wreck Removal (2007, in force 2015) = fills a gap between UNCLOS and national law. Applicable in EEZ (and voluntarily in territorial waters). Obliges owner to: promptly report wreck, assess risk, take measures, remove wreck if hazardous. Mandatory insurance for vessels > 300 GT. Insurance certificate (Wreck Removal Certificate) issued by flag state."},
    {q:"What is the mandatory 'survey' to maintain SOLAS certificates?",opts:["A commercial visit","Periodic inspection of vessel by an accredited body (classification society or flag state) to verify compliance and renew certificates","A PSC inspection","A customs visit"],correct:1,expl:"SOLAS survey = mandatory periodic inspection. Safety certificate (5 years): initial survey + intermediate surveys (2.5 years) + annual surveys. Conducted by: classification society approved by flag state, or directly by flag state. After major accident: special survey required before resuming activity. Without valid survey = expired certificates = PSC can detain vessel."},
  ],
  es:[
    {q:"¿Qué es el 'vínculo genuino' entre un buque y su Estado de pabellón?",opts:["Un contrato de seguros","Requisito CONVEMAR Art.91: vínculo real y efectivo entre el Estado de pabellón y el buque — el Estado debe ejercer efectivamente su jurisdicción","Un acuerdo comercial","Un certificado de navegabilidad"],correct:1,expl:"Vínculo genuino (CONVEMAR Art.91) = principio según el cual debe existir un vínculo efectivo entre el Estado de pabellón y el buque. En teoría, un Estado no puede conceder su pabellón sin tener un vínculo real con el buque. En la práctica: los pabellones de conveniencia han eludido durante mucho tiempo este principio. Sigue siendo fuente de debate en el derecho marítimo internacional."},
    {q:"¿Qué es el 'derecho a denegar el acceso al puerto'?",opts:["Un derecho absoluto del Estado ribereño","Derecho del Estado ribereño a denegar el acceso a su puerto a un buque extranjero en determinadas condiciones — pero con límites (socorro marítimo, CONVEMAR)","Un derecho comercial del puerto","Un derecho reservado a los Estados miembros de la OMI"],correct:1,expl:"Derecho a denegar el acceso al puerto = derecho soberano del Estado ribereño. El Estado puede denegar el acceso por: razones de seguridad, protección medioambiental, sanciones internacionales. LÍMITE IMPORTANTE: si un buque está en peligro (Art.98 CONVEMAR, SAR 1979), la obligación de asistencia puede primar. El caso Prestige (2002) mostró las dramáticas consecuencias de la negativa de un puerto de refugio."},
    {q:"¿Qué es 'QUALSHIP 21' (USCG Quality Shipping for the 21st Century)?",opts:["Un programa de formación","Programa USCG que recompensa a los buques con un excelente historial PSC — inspección reducida · acceso prioritario a los puertos americanos","Un certificado de navegabilidad","Un programa de la OMI"],correct:1,expl:"QUALSHIP 21 = programa USCG creado en 2001. Recompensa a los buques con un excelente historial PSC (0 deficiencias en 3 años de inspecciones). Ventajas: inspección mínima, prioridad en puestos de atraque, reconocimiento oficial. Objetivo: alentar a los armadores a mantener buques de alta calidad."},
    {q:"¿Qué es el 'Convenio FAL' de la OMI?",opts:["Un convenio sobre la seguridad de los buques","Convenio de facilitación del tráfico marítimo internacional (1965) — estandariza las formalidades portuarias para reducir los tiempos de escala","Un convenio sobre la contaminación","Un convenio de navegación"],correct:1,expl:"Convenio FAL (Facilitación del Tráfico Marítimo Internacional, 1965) = simplifica y estandariza las formalidades portuarias. Formularios normalizados (formularios FAL) para: declaración general, lista de personas a bordo, lista de mercancías, declaración de salud marítima, declaración de protección del buque. Desde 2017: declaración electrónica obligatoria (e-FAL)."},
    {q:"¿Qué es el practicaje marítimo y su responsabilidad jurídica?",opts:["Un servicio opcional","Servicio de guía del buque en aguas portuarias por un experto local — obligatorio en la mayoría de los puertos · responsabilidad compartida capitán/práctico","Un servicio comercial","Un servicio reservado a los grandes buques"],correct:1,expl:"Practicaje marítimo = servicio de guía en aguas portuarias. Obligatorio en la mayoría de los puertos. Estatuto jurídico: el práctico es un asesor técnico pero el CAPITÁN sigue siendo el mando y responsable. Si hay accidente con práctico a bordo: responsabilidad compartida según las circunstancias. En muchos países: responsabilidad del práctico limitada por la ley."},
    {q:"¿Qué es la lista de 'buques prioritarios' del Paris MOU?",opts:["Una lista de armadores VIP","Lista de buques seleccionados con prioridad para inspección PSC basándose en su perfil de riesgo (edad, pabellón, historial de deficiencias)","Una lista de buques militares","Una lista de buques nuevos"],correct:1,expl:"Buques prioritarios = buques seleccionados con prioridad para inspección PSC según su Factor de Selección (TF) calculado por el sistema THETIS. Factores: antigüedad del buque, historial de deficiencias, actuación del pabellón, tipo de buque, último puerto de inspección. Sistema transparente publicado en el sitio web del Paris MOU."},
    {q:"¿Qué es la 'lista negra' de pabellones del Paris MOU?",opts:["Una lista de piratas","Clasificación anual de los Estados de pabellón según su tasa de retención — lista negra = actuación PSC insuficiente · buques inspeccionados sistemáticamente","Una lista de puertos peligrosos","Una lista de buques robados"],correct:1,expl:"Lista negra Paris MOU = lista negra de pabellones publicada anualmente. Clasificación: Blanca (buena actuación), Gris (actuación media, vigilancia), Negra (mala actuación, tasa de retención elevada). Si pabellón lista negra: buques de ese pabellón inspeccionados SISTEMÁTICAMENTE en cada escala en los puertos Paris MOU."},
    {q:"¿Qué es un 'acuerdo de agente embarcado' (shiprider agreement) en derecho marítimo internacional?",opts:["Un acuerdo de tripulación","Acuerdo bilateral que permite a agentes de un Estado embarcar en buques patrulleros de otro Estado para ejercer jurisdicción compartida — antidroga · antipiratería","Un acuerdo de remolque","Un acuerdo comercial"],correct:1,expl:"Acuerdo de agente embarcado = acuerdo bilateral de derecho marítimo que permite a agentes de un Estado embarcar en patrulleros de otro Estado para ejercer su jurisdicción nacional en aguas del Estado B. Utilizado principalmente en la lucha contra el narcotráfico (Caribe) y la piratería (Cuerno de África)."},
    {q:"¿Qué es la reglamentación de los Dispositivos de Separación del Tráfico (ZTS) (COLREG Regla 10)?",opts:["Una norma meteorológica","Reglamentación de las zonas de tráfico separado en aproximaciones portuarias y estrechos — canales obligatorios · corredores de navegación","Un reglamento comercial","Un acuerdo entre armadores"],correct:1,expl:"ZTS (Zonas de Tráfico Separado) = COLREG Regla 10. Zonas de navegación definidas en las aproximaciones portuarias y estrechos concurridos. Los buques deben utilizar los corredores apropiados. El Estado ribereño puede establecer ZTS en sus aguas. Incumplimiento = infracción COLREG + responsabilidad civil + posible responsabilidad penal."},
    {q:"¿Qué es la obligación de 'notificación previa' antes de la entrada en un puerto?",opts:["Una recomendación opcional","Obligación legal de notificar al puerto de destino con 24-96h de antelación — información transmitida: buque, carga, tripulación, estado del buque","Un acuerdo comercial","Una obligación aduanera únicamente"],correct:1,expl:"Notificación previa = obligación reglamentaria en la mayoría de los Estados. Plazo: mínimo 24h (algunos puertos 48-96h). Información: nombre/pabellón/MMSI, puerto de procedencia, hora de llegada estimada, naturaleza de la carga, número de personas a bordo, estado del buque. Sirve para: selección PSC, preparación de aduanas, gestión portuaria."},
    {q:"¿Cuál es la obligación de 'investigación de accidentes' del Estado de pabellón?",opts:["Asistencia financiera","Obligación del Estado de pabellón de realizar una investigación oficial sobre los accidentes graves ocurridos a sus buques — Resolución OMI A.884(21)","Un tipo de seguro","Un acuerdo de salvamento"],correct:1,expl:"Investigación del Estado de pabellón = obligación CONVEMAR + Resolución OMI A.884(21). Tras todo accidente grave (pérdida del buque, muerte, contaminación importante): el Estado de pabellón DEBE realizar una investigación oficial independiente. Objetivo: determinar las causas, recomendar mejoras, prevenir la recurrencia. Informe enviado a la OMI."},
    {q:"¿Qué es el 'derecho a denegar la salida' del PSC?",opts:["Un derecho comercial","Derecho del PSC a denegar la autorización de salida de un buque hasta la corrección de las deficiencias graves — puede durar días o semanas","Un derecho militar","Un derecho de la OMI"],correct:1,expl:"Derecho del PSC a denegar la salida = poder central del PSC. Si se detectan deficiencias graves → el PSC puede emitir una 'orden de retención'. El buque NO PUEDE zarpar hasta que: se corrijan las deficiencias, o se obtenga una exención. Costes: tasas portuarias (~€10.000-50.000/día), pérdida de flete, penalizaciones por retraso."},
    {q:"¿Qué es el 'Acuerdo sobre medidas del Estado rector del puerto' (PSMA) de la OMI?",opts:["Un acuerdo comercial","Acuerdo de la OMI (2009) que permite a los Estados inspeccionar y denegar la entrada a buques pesqueros INDNR en sus puertos","Un acuerdo de seguridad","Un acuerdo sobre el practicaje"],correct:1,expl:"PSMA (Port State Measures Agreement) 2009 = primer acuerdo internacional vinculante de la OMI específicamente dedicado a combatir la pesca INDNR (ilegal, no declarada y no reglamentada). Permite a los Estados inspeccionar buques pesqueros en sus puertos, denegar la entrada a buques sospechosos. En vigor desde 2016."},
    {q:"¿Qué es el 'Convenio de Nairobi' (2007) sobre extracción de pecios?",opts:["Un convenio africano","Convenio internacional (2007, en vigor 2015) que obliga al propietario del buque a retirar los pecios peligrosos y a contar con un seguro — aplicable en la ZEE","Un convenio de pesca","Un acuerdo portuario"],correct:1,expl:"Convenio de Nairobi sobre extracción de pecios (2007, en vigor 2015) = llena una laguna entre CONVEMAR y el derecho nacional. Aplicable en la ZEE. Obliga al propietario a: notificar rápidamente el pecio, evaluar el riesgo, tomar medidas, retirar el pecio si es peligroso. Seguro obligatorio para buques > 300 TB."},
    {q:"¿Qué es la 'inspección de reconocimiento' obligatoria para mantener los certificados SOLAS?",opts:["Una visita comercial","Inspección periódica del buque por un organismo acreditado para verificar la conformidad y renovar los certificados","Una inspección PSC","Una visita aduanera"],correct:1,expl:"Reconocimiento SOLAS = inspección periódica obligatoria. Certificado de seguridad (5 años): reconocimiento inicial + reconocimientos intermedios (2,5 años) + reconocimientos anuales. Realizado por: sociedad de clasificación aprobada por el Estado de pabellón, o directamente por el Estado de pabellón. Sin reconocimiento válido = certificados caducados = PSC puede retener el buque."},
  ],
  pt:[
    {q:"O que é o 'vínculo genuíno' entre um navio e o seu Estado de bandeira?",opts:["Um contrato de seguros","Requisito UNCLOS Art.91: vínculo real e efetivo entre o Estado de bandeira e o navio — o Estado deve exercer efetivamente a sua jurisdição","Um acordo comercial","Um certificado de navegabilidade"],correct:1,expl:"Vínculo genuíno (UNCLOS Art.91) = princípio segundo o qual deve existir um vínculo efetivo entre o Estado de bandeira e o navio. Em teoria, um Estado não pode conceder a sua bandeira sem ter um vínculo real com o navio. Na prática: as bandeiras de conveniência têm contornado este princípio durante muito tempo. Continua a ser fonte de debate no direito marítimo internacional."},
    {q:"O que é o 'direito de recusar a entrada no porto'?",opts:["Um direito absoluto do Estado costeiro","Direito do Estado costeiro de recusar o acesso ao seu porto a um navio estrangeiro em certas condições — mas com limites (socorro marítimo, UNCLOS)","Um direito comercial do porto","Um direito reservado aos estados membros da IMO"],correct:1,expl:"Direito de recusar a entrada no porto = direito soberano do Estado costeiro. O Estado pode recusar o acesso por: razões de segurança, proteção ambiental, sanções internacionais. LIMITE IMPORTANTE: se um navio está em perigo (Art.98 UNCLOS, SAR 1979), a obrigação de assistência pode prevalecer. O caso Prestige (2002) mostrou as dramáticas consequências da recusa de um porto de refúgio."},
    {q:"O que é o 'QUALSHIP 21' (USCG Quality Shipping for the 21st Century)?",opts:["Um programa de formação","Programa USCG que recompensa os navios com um excelente historial PSC — inspeção reduzida · acesso prioritário aos portos americanos","Um certificado de navegabilidade","Um programa da IMO"],correct:1,expl:"QUALSHIP 21 = programa USCG criado em 2001. Recompensa os navios com excelente historial PSC (0 deficiências em 3 anos de inspeções). Vantagens: inspeção mínima, prioridade nos postos de atracação, reconhecimento oficial. Objetivo: encorajar os armadores a manter navios de alta qualidade."},
    {q:"O que é a 'Convenção FAL' da IMO?",opts:["Uma convenção sobre a segurança dos navios","Convenção de facilitação do tráfego marítimo internacional (1965) — standardiza as formalidades portuárias para reduzir os tempos de escala","Uma convenção sobre poluição","Uma convenção de navegação"],correct:1,expl:"Convenção FAL (Facilitação do Tráfego Marítimo Internacional, 1965) = simplifica e standardiza as formalidades portuárias. Formulários normalizados (FAL forms) para: declaração geral, lista de pessoas a bordo, lista de mercadorias, declaração de saúde marítima, declaração de proteção do navio. Desde 2017: declaração eletrónica obrigatória (e-FAL)."},
    {q:"O que é a praticagem marítima e a sua responsabilidade jurídica?",opts:["Um serviço opcional","Serviço de guia do navio em águas portuárias por um especialista local — obrigatório na maioria dos portos · responsabilidade partilhada capitão/prático","Um serviço comercial","Um serviço reservado aos grandes navios"],correct:1,expl:"Praticagem marítima = serviço de guia em águas portuárias por especialista local. Obrigatório na maioria dos portos. Estatuto jurídico: o prático é um conselheiro técnico mas o CAPITÃO continua a ser o comandante e responsável. Se acidente com prático a bordo: responsabilidade partilhada segundo as circunstâncias. Em muitos países: responsabilidade do prático limitada por lei."},
    {q:"O que é a lista de 'navios prioritários' do Paris MOU?",opts:["Uma lista de armadores VIP","Lista de navios selecionados como prioritários para inspeção PSC com base no seu perfil de risco (idade, bandeira, historial de deficiências)","Uma lista de navios militares","Uma lista de navios novos"],correct:1,expl:"Navios prioritários = navios selecionados como prioritários para inspeção PSC segundo o seu Target Factor (TF) calculado pelo sistema THETIS. Fatores: idade do navio, historial de deficiências, desempenho da bandeira, tipo de navio, último porto de inspeção. Sistema transparente publicado no site do Paris MOU."},
    {q:"O que é a 'lista negra' de bandeiras do Paris MOU?",opts:["Uma lista de piratas","Classificação anual dos Estados de bandeira pela taxa de retenção — lista negra = desempenho PSC insuficiente · navios inspecionados sistematicamente","Uma lista de portos perigosos","Uma lista de navios roubados"],correct:1,expl:"Lista negra Paris MOU = lista negra de bandeiras publicada anualmente. Classificação: Branca (bom desempenho), Cinzenta (desempenho médio, vigilância), Negra (mau desempenho, taxa de retenção elevada). Se bandeira lista negra: navios dessa bandeira inspecionados SISTEMATICAMENTE em cada escala nos portos Paris MOU."},
    {q:"O que é um 'acordo de agente embarcado' (shiprider agreement) no direito marítimo internacional?",opts:["Um acordo de tripulação","Acordo bilateral que permite a agentes de um estado embarcar em navios patrulha de outro estado para exercer jurisdição partilhada — anti-droga · anti-pirataria","Um acordo de reboque","Um acordo comercial"],correct:1,expl:"Acordo de agente embarcado = acordo bilateral de direito marítimo que permite a agentes de um Estado A embarcar em navios patrulha do Estado B para exercer a sua jurisdição nacional nas águas de B. Utilizado principalmente na luta contra o tráfico de droga (Caraíbas) e a pirataria (Corno de África)."},
    {q:"O que é a regulamentação das Zonas de Separação de Tráfego (ZST) (COLREG Regra 10)?",opts:["Uma regra meteorológica","Regulamentação das zonas de separação de tráfego nas aproximações portuárias e estreitos — canais obrigatórios · corredores de navegação","Um regulamento comercial","Um acordo entre armadores"],correct:1,expl:"ZST (Zonas de Separação de Tráfego) = COLREG Regra 10. Zonas de navegação definidas nas aproximações portuárias e estreitos movimentados. Os navios devem utilizar os corredores apropriados. O Estado costeiro pode estabelecer ZST nas suas águas. Incumprimento = violação COLREG + responsabilidade civil + possível responsabilidade penal."},
    {q:"O que é a obrigação de 'notificação prévia' antes da entrada num porto?",opts:["Uma recomendação opcional","Obrigação legal de notificar o porto de destino 24-96h antes da chegada — informação transmitida: navio, carga, tripulação, estado do navio","Um acordo comercial","Uma obrigação aduaneira apenas"],correct:1,expl:"Notificação prévia = obrigação regulamentar na maioria dos estados. Prazo: mínimo 24h (alguns portos 48-96h). Informação: nome/bandeira/MMSI, porto de origem, hora de chegada estimada, natureza da carga, pessoas a bordo, estado do navio. Serve para: seleção PSC, preparação alfandegária, gestão portuária."},
    {q:"Qual é a obrigação de 'investigação de acidentes' do Estado de bandeira?",opts:["Assistência financeira","Obrigação do Estado de bandeira de conduzir uma investigação oficial sobre acidentes graves ocorridos com os seus navios — Resolução IMO A.884(21)","Um tipo de seguro","Um acordo de salvamento"],correct:1,expl:"Investigação do Estado de bandeira = obrigação UNCLOS + Resolução IMO A.884(21). Após qualquer acidente grave (perda do navio, morte, poluição importante): o Estado de bandeira DEVE conduzir uma investigação oficial independente. Objetivo: determinar causas, recomendar melhorias, prevenir recorrência. Relatório enviado à IMO."},
    {q:"O que é o 'direito de recusar a partida' do PSC?",opts:["Um direito comercial","Direito do PSC de recusar autorização de partida até à correção das deficiências graves — pode durar dias ou semanas","Um direito militar","Um direito da IMO"],correct:1,expl:"Direito PSC de recusar a partida = poder central do PSC. Se deficiências graves detetadas → o PSC pode emitir uma 'ordem de retenção'. O navio NÃO PODE partir até que: as deficiências sejam corrigidas, ou obtenha uma isenção. Custos: taxas portuárias (~€10.000-50.000/dia), perda de frete, penalidades por atraso."},
    {q:"O que é o 'Acordo sobre Medidas do Estado do Porto' (PSMA) da IMO?",opts:["Um acordo comercial","Acordo da IMO (2009) que permite aos estados inspecionar e recusar navios de pesca INN nos seus portos (pesca ilegal, não declarada e não regulamentada)","Um acordo de segurança","Um acordo sobre praticagem"],correct:1,expl:"PSMA (Port State Measures Agreement) 2009 = primeiro acordo internacional vinculativo da IMO especificamente dedicado ao combate à pesca INN (ilegal, não declarada e não regulamentada). Permite aos estados inspecionar navios de pesca nos seus portos, recusar a entrada a navios suspeitos. Em vigor desde 2016."},
    {q:"O que é a 'Convenção de Nairóbi' (2007) sobre a remoção de naufrágios?",opts:["Uma convenção africana","Convenção internacional (2007, em vigor 2015) que obriga o proprietário do navio a remover os naufrágios perigosos e a ter seguro — aplicável na ZEE","Uma convenção de pesca","Um acordo portuário"],correct:1,expl:"Convenção de Nairóbi sobre Remoção de Naufrágios (2007, em vigor 2015) = preenche uma lacuna entre UNCLOS e o direito nacional. Aplicável na ZEE. Obriga o proprietário a: notificar prontamente o naufrágio, avaliar o risco, tomar medidas, remover o naufrágio se perigoso. Seguro obrigatório para navios > 300 AB."},
    {q:"O que é a 'visita de controlo' (survey) obrigatória para manter os certificados SOLAS?",opts:["Uma visita comercial","Inspeção periódica do navio por um organismo acreditado para verificar a conformidade e renovar os certificados","Uma inspeção PSC","Uma visita aduaneira"],correct:1,expl:"Survey SOLAS = inspeção periódica obrigatória. Certificado de segurança (5 anos): survey inicial + surveys intermédios (2,5 anos) + surveys anuais. Realizado por: sociedade de classificação aprovada pelo Estado de bandeira, ou diretamente pelo Estado de bandeira. Sem survey válido = certificados expirados = PSC pode reter o navio."},
  ],
};

function QuestionBank({ lang }) {
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [done,setDone]=useState(false);
  const questions=BANK[lang]||BANK.fr;const [shuffled]=useState(()=>questions.map(shuffleQuestionOptions));const q=shuffled[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else setDone(true);};
  if(done)return(<div style={{textAlign:"center",padding:"20px 0"}}><div style={{fontSize:48}}>{score>=12?"🏆":score>=8?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:20,color:C.white,margin:"8px 0 4px"}}>{score}/{questions.length}</div><div style={{fontSize:14,color:C.gold2}}>{Math.round(score/questions.length*100)}%</div></div>);
  return(<div>
    <div style={{display:"flex",justifyContent:"space-between",marginBottom:10}}><div style={{fontSize:10,color:C.muted}}>{cur+1}/{questions.length}</div><div style={{fontSize:12,color:C.gold2,fontWeight:700}}>✓ {score}</div></div>
    <div style={{height:3,background:"rgba(255,255,255,0.08)",borderRadius:3,marginBottom:12,overflow:"hidden"}}><div style={{height:"100%",width:`${(cur/questions.length)*100}%`,background:`linear-gradient(90deg,${C.steel},${C.gold2})`}}/></div>
    <div style={{fontSize:13,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:12}}>{q.q}</div>
    <div style={{display:"flex",flexDirection:"column",gap:8,marginBottom:10}}>
      {q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;}}return<button key={i} onClick={()=>pick(i)} style={{padding:"10px 12px",borderRadius:12,background:bg,border:`1.5px solid ${bd}`,color:C.muted,fontSize:12,textAlign:"left",cursor:answered?"default":"pointer",lineHeight:1.4}}>{opt}</button>;})}
    </div>
    {answered&&<><div style={{padding:"10px 12px",borderRadius:10,marginBottom:10,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,fontSize:11,color:C.white,lineHeight:1.6}}>{q.expl}</div>
    <button onClick={next} style={{width:"100%",padding:"11px 0",border:"none",borderRadius:12,background:`linear-gradient(135deg,${C.steel},${C.gold2})`,fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?(lang==="fr"?"SUIVANT →":lang==="en"?"NEXT →":lang==="es"?"SIGUIENTE →":"PRÓXIMO →"):(lang==="fr"?"TERMINER":lang==="en"?"FINISH":lang==="es"?"TERMINAR":"TERMINAR")}</button></>}
  </div>);
}

function Stars(){const s=Array.from({length:14},()=>({x:Math.random()*100,y:Math.random()*100,sz:Math.random()>0.7?2:1.5,dur:2+Math.random()*4,delay:Math.random()*6}));return(<><div style={{position:"fixed",inset:0,pointerEvents:"none",zIndex:0}}>{s.map((st,i)=><div key={i} style={{position:"absolute",left:`${st.x}%`,top:`${st.y}%`,width:st.sz,height:st.sz,borderRadius:"50%",background:"white",opacity:0,animation:`tw ${st.dur}s ease-in-out ${st.delay}s infinite`}}/>)}</div><style>{`@keyframes tw{0%,100%{opacity:0}50%{opacity:0.35}}@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}@keyframes correctPop{0%{transform:scale(0.85)}60%{transform:scale(1.1)}100%{transform:scale(1)}}@keyframes wrongShake{0%,100%{transform:translateX(0)}25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}`}</style></>);}
function Card({children,style={}}){return<div style={{background:"rgba(13,31,60,0.75)",border:`1px solid ${C.border}`,borderRadius:18,padding:"16px",...style}}>{children}</div>;}
function GLine(){return<div style={{height:1,margin:"14px 0",background:`linear-gradient(90deg,transparent,${C.steel}33,${C.gold2}33,transparent)`}}/>;}
function SL({icon,text,color}){return<div style={{display:"flex",alignItems:"center",gap:10,margin:"20px 0 12px"}}><span style={{fontSize:20}}>{icon}</span><div style={{fontFamily:"'Cinzel',serif",fontSize:12,fontWeight:700,color:color||C.gold,letterSpacing:2}}>{text}</div><div style={{flex:1,height:1,background:`linear-gradient(90deg,${color||C.gold}44,transparent)`}}/></div>;}

function QuizComp({questions,t,onComplete}){
  const [shuffled]=useState(()=>questions.map(shuffleQuestionOptions));
  const [cur,setCur]=useState(0);const [sel,setSel]=useState(null);const [answered,setAnswered]=useState(false);const [score,setScore]=useState(0);const [answers,setAnswers]=useState([]);const [done,setDone]=useState(false);
  const q=shuffled[cur];const isOk=sel===q.correct;
  const pick=i=>{if(answered)return;setSel(i);setAnswered(true);if(i===q.correct)setScore(s=>s+1);setAnswers(a=>[...a,{i,ok:i===q.correct}]);};
  const next=()=>{if(cur<questions.length-1){setCur(c=>c+1);setSel(null);setAnswered(false);}else{setDone(true);onComplete(score+(isOk?1:0));}};
  if(done){const fs=score;const pct=Math.round(fs/questions.length*100);const xp=fs>=4?200:fs===3?120:60;return(<Card style={{textAlign:"center"}}><div style={{fontSize:52,marginBottom:8}}>{pct===100?"🏆":pct>=80?"🎖️":"📚"}</div><div style={{fontFamily:"'Cinzel',serif",fontSize:28,fontWeight:900,color:C.white,marginBottom:4}}>{fs}/{questions.length}</div><div style={{display:"inline-block",marginTop:8,padding:"6px 16px",borderRadius:20,background:"rgba(201,146,42,0.15)",border:`1px solid ${C.gold}44`,fontSize:14,color:C.gold2,fontWeight:700}}>+{xp} {t.xp} ⭐</div><GLine/><div style={{display:"flex",justifyContent:"center",gap:8,marginTop:8}}>{answers.map((a,i)=><div key={i} style={{width:32,height:32,borderRadius:"50%",background:a.ok?C.green:C.red,display:"flex",alignItems:"center",justifyContent:"center",fontSize:14,color:C.white}}>{a.ok?"✓":"✗"}</div>)}</div></Card>);}
  return(<Card style={{border:`1px solid ${C.steel}33`}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div style={{fontSize:11,letterSpacing:3,color:C.steel,fontFamily:"'Cinzel',serif"}}>{t.quiz}</div><div style={{fontSize:12,color:C.muted}}>{t.question} {cur+1} {t.ofQ} {questions.length}</div></div><div style={{display:"flex",gap:6,marginBottom:16}}>{questions.map((_,i)=><div key={i} style={{flex:1,height:3,borderRadius:3,background:i<cur?(answers[i]?.ok?C.green:C.red):i===cur?C.steel:"rgba(255,255,255,0.1)"}}/>)}</div><div style={{fontSize:14,fontWeight:700,color:C.white,lineHeight:1.5,marginBottom:16}}>{q.q}</div><div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:14}}>{q.opts.map((opt,i)=>{let bg="rgba(255,255,255,0.05)",bd="rgba(255,255,255,0.1)",anim="none";if(answered){if(i===q.correct){bg="rgba(30,138,74,0.2)";bd=C.green;anim="correctPop 0.4s ease";}else if(i===sel){bg="rgba(192,57,43,0.2)";bd=C.red;anim="wrongShake 0.4s ease";}}return<button key={i} onClick={()=>pick(i)} style={{padding:"12px 14px",borderRadius:14,background:bg,border:`1.5px solid ${bd}`,color:answered&&(i===q.correct||i===sel)?C.white:C.muted,fontSize:13,textAlign:"left",cursor:answered?"default":"pointer",animation:anim,display:"flex",alignItems:"center",gap:10,lineHeight:1.4}}><div style={{width:26,height:26,borderRadius:"50%",flexShrink:0,background:answered&&i===q.correct?C.green:answered&&i===sel?C.red:"rgba(255,255,255,0.1)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:700,color:C.white}}>{answered&&i===q.correct?"✓":answered&&i===sel?"✗":String.fromCharCode(65+i)}</div><span>{opt}</span></button>;})} </div>{answered&&<div style={{padding:"12px 14px",borderRadius:12,marginBottom:14,background:isOk?"rgba(30,138,74,0.12)":"rgba(192,57,43,0.1)",border:`1px solid ${isOk?C.green:C.red}44`,animation:"fadeUp 0.4s ease"}}><div style={{fontSize:12,fontWeight:700,marginBottom:4,color:isOk?C.green:C.red}}>{isOk?t.correct:t.wrong}</div><div style={{fontSize:11,color:C.muted,fontWeight:600,marginBottom:2}}>{t.expl}</div><div style={{fontSize:12,color:C.white,lineHeight:1.6}}>{q.expl}</div></div>}{answered&&<button onClick={next} style={{width:"100%",padding:"14px 0",border:"none",borderRadius:14,background:`linear-gradient(135deg,${C.steel},${C.gold})`,fontFamily:"'Cinzel',serif",fontSize:13,fontWeight:700,letterSpacing:2,color:C.white,cursor:"pointer"}}>{cur<questions.length-1?t.next:t.finish}</button>}</Card>);
}

